window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch08"]={"id": "ch08", "title": "第八章 蛋白质组学", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第八章 蛋白质组学", "slides": [{"i": 0, "sec": "第一节 蛋白质组学概述", "title": "蛋白质组学概述与蛋白质组定义", "notes": "本页为第八章开篇，首先从分子生物学中心法则出发，说明DNA序列通过编码蛋白质序列决定蛋白质三维结构，进而决定其功能，因此基因组计划的最终目的仍是理解蛋白质如何实现生命活动。由此引出“蛋白质组”与“蛋白质组学”的概念：蛋白质组指一个特定样本（细胞、组织或器官）中所表达的一整套蛋白质；蛋白质组学则是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量分析，以及蛋白质功能、细胞定位、翻译后修饰和蛋白质相互作用等。页中还介绍了Proteomics和Proteome术语的来源，指出其由Marc Wilkins等人在20世纪90年代初提出，与基因组学、基因组相对应，Proteome由PROTEin与genOME杂合而成，omics代表全局性、整体性的研究方式。该页属于第一节蛋白质组学概述，是理解后续分离鉴定技术的重要概念基础。", "page": 156, "level": "掌握", "img": "assets/img/ch08/p156.jpg", "anim": null, "fig": null, "points": ["中心法则：DNA→蛋白质序列→三维结构→功能，基因组计划最终目的是理解蛋白质如何实现生命活动", "蛋白质组：一个特定样本（细胞、组织或器官）中所表达的一整套蛋白质", "蛋白质组学：对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量分析", "蛋白质组学是后基因组时代生命科学研究的核心内容之一", "⚠️ 考点/易错点：蛋白质组定义易考：指一个特定样本中表达的一整套蛋白质，强调“特定样本/动态”，不要与基因组（全部遗传信息）混淆；蛋白质组学不仅鉴定定量，还包括定位、修饰与相互作用。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "根据蛋白质组与蛋白质组学的定义，下列哪项最准确？", "o": ["A. 蛋白质组指一个物种基因组中全部编码蛋白质的基因序列", "B. 蛋白质组指一个特定样本中所表达的一整套蛋白质，蛋白质组学是对其中所有蛋白质进行系统研究", "C. 蛋白质组学仅指对蛋白质进行三维结构解析", "D. 蛋白质组指所有翻译后修饰酶的总称"], "a": "B", "e": "蛋白质组指一个特定样本（细胞、组织或器官）中所表达的一整套蛋白质；蛋白质组学则是对样本中所有蛋白质进行系统研究，包括鉴定、定量、功能、定位、修饰和相互作用等。"}, "cards": [{"front": "什么是蛋白质组和蛋白质组学？", "back": "蛋白质组指一个特定样本（细胞、组织或器官）中所表达的一整套蛋白质；蛋白质组学是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量分析。", "mnemonic": "基因组是“图纸”，蛋白质组是“实际施工队”；蛋白质组学研究“施工队”在干什么。", "useImg": false}]}, {"i": 1, "sec": "第一节 蛋白质组学概述", "title": "基因组学发展历程图示", "notes": "本页主要为图8-1相关内容的延续，OCR文本严重混乱，但结合上下文可判断其展示的是基因组学研究发展的时间线或里程碑式图示。图中上半部分可能概括了20世纪生命科学中基因研究的重要进展，下半部分则引出人类基因组计划的里程碑。阅读此类图时应重点关注时间轴、关键事件节点以及从结构基因组学到功能基因组学的转变。该页的核心意义在于说明基因组学研究取得了巨大成就，为蛋白质组学的产生提供了背景和推动力。由于基因组序列测定并不能直接解释生命活动，科学家逐渐认识到必须从蛋白质层面研究基因功能，因此蛋白质组学成为后基因组时代的重要研究方向。本页属于第一节蛋白质组学概述中的基因组学产生及研究进展部分。", "page": 157, "level": "理解", "img": "assets/img/ch08/p157.jpg", "anim": null, "fig": "看图时先找时间轴，按时间顺序梳理关键事件节点；重点观察从结构基因组学到功能基因组学的转变节点，理解基因组学成就如何为蛋白质组学奠定基础。", "points": ["图8-1展示基因组学研究发展的时间线或里程碑式图示", "关注时间轴、关键事件节点以及从结构基因组学到功能基因组学的转变", "核心意义：基因组学研究取得巨大成就，为蛋白质组学奠定基础", "⚠️ 考点/易错点：易考基因组学到蛋白质组学的逻辑转折：基因组序列测定不能直接解释生命活动，结构基因组学转向功能基因组学，并推动蛋白质组学产生。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于基因组学发展历程图示所体现的意义，下列哪项最符合其核心作用？", "o": ["A. 说明蛋白质组学已经完全取代基因组学", "B. 展示基因组学研究的重要进展，并说明其成就为蛋白质组学产生提供背景和推动力", "C. 证明基因组序列测定可直接解释全部生命活动", "D. 表明人类基因组计划没有取得实质成果"], "a": "B", "e": "该图展示基因组学研究发展的时间线或里程碑，核心意义在于说明基因组学取得巨大成就，但基因组序列并不能直接解释生命活动，从而推动蛋白质组学产生。"}, "cards": null}, {"i": 2, "sec": "第一节 蛋白质组学概述", "title": "人类基因组计划完成与后基因组时代", "notes": "本页继续介绍基因组学研究的成就与局限。人类基因组计划被誉为生命科学领域的“阿波罗计划”，是人类第一次系统、全面地解读和研究人类遗传物质DNA。2000年发布人类基因组工作框架图，2003年宣布完成更精确的人类基因组序列图，2006年完成1号染色体测序图，标志着历时16年的人类基因组计划圆满结束。随着人类基因组序列图完成，生命科学进入后基因组时代，功能基因组学成为研究重心，而蛋白质组学是功能基因组学的核心。2001年Nature和Science在公布人类基因组序列草图的同时，分别发表“And now for the proteome”和“Proteomics in genome land”等述评，呼唤蛋白质组学研究。页末指出基因组学研究的局限：完成全长序列测定只是结构基因组学第一步，接下来需要研究基因功能及其发挥机制，即功能基因组学。", "page": 158, "level": "掌握", "img": "assets/img/ch08/p158.jpg", "anim": null, "fig": null, "points": ["人类基因组计划被誉为生命科学领域的“阿波罗计划”", "2000年发布工作框架图，2003年宣布完成更精确序列图，2006年完成1号染色体测序图，历时16年", "人类基因组序列图完成标志生命科学进入后基因组时代", "后基因组时代以功能基因组学为代表，蛋白质组学是核心内容", "⚠️ 考点/易错点：关键时间点易混：2000年人类基因组工作框架图、2003年更精确序列图、2006年1号染色体完成；后基因组时代核心是功能基因组学，蛋白质组学是其核心。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于人类基因组计划完成与后基因组时代，下列哪项正确？", "o": ["A. 2000年发布人类基因组工作框架图，2003年宣布完成更精确的人类基因组序列图", "B. 人类基因组计划于1990年开始，2000年即完全结束", "C. 后基因组时代的研究重心是重新测定DNA序列", "D. 蛋白质组学与功能基因组学无关"], "a": "A", "e": "2000年发布人类基因组工作框架图，2003年宣布完成更精确的人类基因组序列图，2006年完成1号染色体测序图，标志历时16年的人类基因组计划圆满结束。后基因组时代功能基因组学成为重心，蛋白质组学是其核心。"}, "cards": [{"front": "人类基因组计划的关键时间节点有哪些？", "back": "2000年发布工作框架图；2003年宣布完成更精确序列图；2006年完成1号染色体测序图，历时16年圆满结束。", "mnemonic": "2000框架、2003精确、2006收尾，16年完成“阿波罗计划”。", "useImg": false}]}, {"i": 3, "sec": "第一节 蛋白质组学概述", "title": "蛋白质组学的产生及研究进展", "notes": "本页进入第一节第二部分，阐述蛋白质组学的产生及研究进展。蛋白质是生理功能的执行者和生命现象的直接体现者，研究蛋白质结构和功能可直接阐明生命在生理或病理条件下的变化机制。蛋白质的存在形式和活动规律，如翻译后修饰、蛋白质间相互作用及蛋白质构象等，仍依赖对蛋白质本身的研究。蛋白质组学以细胞内全部蛋白质的存在及其活动方式为研究对象，是后基因组时代生命科学研究的核心内容之一。2001年Science将蛋白质组学列为六大研究热点之一，热度仅次于干细胞研究。页中还概述了蛋白质组学技术已广泛应用于蛋白质鉴定、翻译后修饰和蛋白质-蛋白质互作等领域，并重点提到蛋白质分离与鉴定方面的进展，尤其是双向凝胶电泳结合生物质谱技术，第一相采用固相化pH梯度胶条，第二相采用SDS-PAGE，可获得分辨率达数千点的蛋白质图谱。", "page": 159, "level": "掌握", "img": "assets/img/ch08/p159.jpg", "anim": null, "fig": null, "points": ["蛋白质是生理功能的执行者和生命现象的直接体现者", "研究蛋白质结构和功能可直接阐明生命在生理或病理条件下的变化机制", "蛋白质的存在形式和活动规律（翻译后修饰、相互作用、构象）依赖对蛋白质本身的研究", "蛋白质组学以细胞内全部蛋白质的存在及其活动方式为研究对象", "蛋白质组学是后基因组时代生命科学研究的核心内容", "⚠️ 考点/易错点：易考蛋白质组学产生原因：蛋白质是生理功能执行者和生命现象直接体现者；翻译后修饰、相互作用、构象等必须直接研究蛋白质，不能仅由基因推断。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于蛋白质组学的产生及研究进展，下列哪项最准确？", "o": ["A. 蛋白质是生理功能的执行者和生命现象的直接体现者，研究蛋白质结构和功能可直接阐明生命变化机制", "B. 蛋白质组学只研究基因序列，不研究蛋白质本身", "C. 蛋白质组学在2001年被Science列为唯一研究热点", "D. 蛋白质组学与后基因组时代无关"], "a": "A", "e": "蛋白质是生理功能的执行者和生命现象的直接体现者，研究蛋白质结构和功能可直接阐明生命在生理或病理条件下的变化机制。蛋白质组学是后基因组时代生命科学研究的核心内容之一。"}, "cards": [{"front": "为什么蛋白质组学是后基因组时代的核心内容？", "back": "蛋白质是生理功能的执行者和生命现象的直接体现者；研究蛋白质结构和功能可直接阐明生命在生理或病理条件下的变化机制；蛋白质的存在形式和活动规律依赖对蛋白质本身的研究。", "mnemonic": "基因是“剧本”，蛋白质是“演员”；光有剧本不够，还得看演员怎么演。", "useImg": false}]}, {"i": 4, "sec": "第一节 蛋白质组学概述", "title": "蛋白质大规模分离鉴定技术概述与二维电泳", "notes": "本页进入第二节蛋白质的大规模分离鉴定技术。首先指出蛋白质具有多样性与易变性，使蛋白质组学研究技术远比基因技术复杂困难。由于基因拼接和翻译后修饰，生物体中蛋白质数目远大于基因数目，一个细胞中蛋白质可多达上万种，拷贝数可能相差几百倍到几十万倍。人的基因组可能有25000~40000个编码基因，蛋白质数量可能达十几万甚至更多。基因相对静态，而蛋白质动态变化，随时间、空间而变化。理想的分离方法应具备超高分辨率，能同时分离成千上万种蛋白质及其修饰物，并与后续鉴定技术有效衔接。二维凝胶电泳利用蛋白质等电点和分子质量进行分离，是蛋白质组分离的关键技术。最早的2-DE由Farrell于1975年提出，根据等电点和分子质量差异连续进行两次电泳。用固相pH梯度干胶条代替两性电解质，配合PROTEAN IEF Cell等电泳仪进行第一向等电聚焦，提高了分辨率和可重复性。", "page": 160, "level": "掌握", "img": "assets/img/ch08/p160.jpg", "anim": null, "fig": null, "points": ["蛋白质具有多样性与易变性，蛋白质组学研究技术远比基因技术复杂困难", "由于基因拼接和翻译后修饰，蛋白质数目远大于基因数目，一个细胞中蛋白质可多达上万种", "蛋白质拷贝数可能相差几百倍到几十万倍", "人的基因组可能有25000~40000个编码基因，蛋白质数量可能达十几万甚至更多", "基因相对静态，而蛋白质动态变化", "⚠️ 考点/易错点：易错点：蛋白质数目远大于基因数目，因基因拼接和翻译后修饰；蛋白质动态、多样、易变，拷贝数差异极大，故分离鉴定远比基因技术复杂。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于蛋白质大规模分离鉴定技术概述与二维电泳，下列哪项正确？", "o": ["A. 生物体中蛋白质数目通常少于基因数目", "B. 蛋白质具有多样性与易变性，使蛋白质组学研究技术远比基因技术复杂困难", "C. 一个细胞中蛋白质种类很少，拷贝数差异也很小", "D. 蛋白质与基因一样相对静态，不随时间空间变化"], "a": "B", "e": "由于基因拼接和翻译后修饰，生物体中蛋白质数目远大于基因数目，一个细胞中蛋白质可多达上万种，拷贝数差异巨大。基因相对静态，而蛋白质动态变化，因此蛋白质组学技术更复杂困难。"}, "cards": [{"front": "为什么蛋白质组学研究比基因组学更复杂困难？", "back": "蛋白质具有多样性与易变性；由于基因拼接和翻译后修饰，蛋白质数目远大于基因数目；一个细胞中蛋白质可多达上万种，拷贝数相差几百倍到几十万倍；基因相对静态，蛋白质动态变化。", "mnemonic": "基因是“静态图书馆”，蛋白质是“动态菜市场”——种类多、数量乱、变化快。", "useImg": false}]}, {"i": 5, "sec": "第一节 蛋白质组学概述", "title": "生物质谱技术及一维/二维色谱-质谱技术", "notes": "本页继续介绍蛋白质鉴定中的质谱技术及色谱-质谱联用策略。MALDI通常与TOF质量分析器联用，分析肽段精确质量；ESI常与离子阱或三级四极杆质谱联用，通过碰撞诱导解离获取肽段碎片信息。离子阱质谱灵敏度高、性能稳定、具备多级质谱能力，广泛用于蛋白质组学研究，但质量精度较低。傅里叶变换离子回旋共振质谱也是一种可捕获离子的仪器，具有高灵敏度、宽动态范围、高分辨率和高精度，可在一次分析中对数百个完整蛋白质分子进行质量测定和定量，并能同时选择几个母离子进行解离，提高鉴定通量，但操作复杂、肽段断裂效率低、价格昂贵。除双向电泳-质谱外，一维电泳（色谱）-质谱和二维色谱-质谱技术也广泛应用，弥补2-DE技术缺陷。一维SDS-PAGE结合MALDI-TOF-MS，或蛋白质复合物酶切后用LC-MS-MS分析，均是有效的蛋白质分离与鉴定策略。", "page": 161, "level": "理解", "img": "assets/img/ch08/p161.jpg", "anim": null, "fig": null, "points": ["MALDI通常与TOF质量分析器联用，分析肽段精确质量", "ESI常与离子阱或三级四极杆质谱联用，通过碰撞诱导解离获取肽段碎片信息", "离子阱质谱灵敏度高、性能稳定、具备多级质谱能力，但质量精度较低", "傅里叶变换离子回旋共振质谱具有高灵敏度、宽动态范围、高分辨率", "⚠️ 考点/易错点：质谱联用易混：MALDI常与TOF联用测肽段精确质量；ESI常与离子阱或三级四极杆联用，经CID获取碎片信息；离子阱灵敏度高、可多级质谱但质量精度较低。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于生物质谱技术及一维/二维色谱-质谱技术，下列哪项正确？", "o": ["A. MALDI通常与TOF质量分析器联用，分析肽段精确质量", "B. ESI通常只与TOF联用，不能与离子阱联用", "C. 离子阱质谱质量精度高，但不具备多级质谱能力", "D. 傅里叶变换离子回旋共振质谱灵敏度低、分辨率低"], "a": "A", "e": "MALDI通常与TOF质量分析器联用，分析肽段精确质量；ESI常与离子阱或三级四极杆质谱联用。离子阱灵敏度高、具备多级质谱能力但质量精度较低；FT-ICR具有高灵敏度、宽动态范围、高分辨率和高精度。"}, "cards": [{"front": "MALDI和ESI分别常与什么质量分析器联用？", "back": "MALDI通常与TOF质量分析器联用，分析肽段精确质量；ESI常与离子阱或三级四极杆质谱联用，通过碰撞诱导解离获取肽段碎片信息。", "mnemonic": "MALDI-TOF测“整重”，ESI-离子阱/四极杆测“碎片”。", "useImg": false}]}, {"i": 6, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "二维色谱-质谱技术（2D-HPLC-MS）", "notes": "本页承接蛋白质大规模分离鉴定技术。首先介绍一种基于IPG胶条等电聚焦与MALDI-TOF-MS联用的方法：用pH5.7~6.0的IPG胶条分离大肠杆菌总蛋白，可鉴定约250个蛋白质，而传统2-DE仅约100个；对小于50 kDa的蛋白质，相对分子质量准确度达0.1%~0.2%，pH准确度约±0.3。该方法省去从2-DE胶向质谱过渡的繁琐操作，将一向IEF与准确、灵敏、高分辨的分子质量测定结合，虽在胶上酶切和直接测序方面仍有问题，但有望成为2-DE替代方法之一。随后重点介绍二维色谱-质谱技术（2D-HPLC-MS）：液相色谱分离蛋白质/多肽具有速度快（数小时 vs 2-DE需1~2天）、溶液状态样品处理方便且易自动化并与质谱联用、适用范围广（疏水、酸性、碱性、>100 kDa或<10 kDa蛋白）等优点。流程为：组织/细胞蛋白混合物经胰蛋白酶裂解成多肽，进行二维色谱分离，再用电喷雾串联质谱测定肽段序列分子质量以鉴定蛋白质。图8-2展示二维色谱-串联质谱分离细胞蛋白质流程：进样→第一维分离→盐浓度梯度洗脱→第二维反相分离→质谱。常见组合为第一维离子交换色谱（或凝胶过滤），第二维反相色谱；反相色谱用有机溶剂流动相，避免盐等添加剂干扰后续质谱。", "page": 162, "level": "掌握", "img": "assets/img/ch08/p162.jpg", "anim": null, "fig": null, "points": ["基于IPG胶条等电聚焦与MALDI-TOF-MS联用的方法可鉴定约250个蛋白质，传统2-DE仅约100个", "对小于50 kDa的蛋白质，相对分子质量准确度达0.1%~0.2%，pH准确度约±0.3", "该方法省去从2-DE胶向质谱过渡的繁琐操作", "将一向IEF与质谱直接联用，提高鉴定效率", "⚠️ 考点/易错点：易考IPG-IEF与MALDI-TOF-MS联用优势：可鉴定约250个蛋白，优于传统2-DE约100个；小于50 kDa蛋白质量准确度达0.1%~0.2%，pH准确度约±0.3。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于二维色谱-质谱技术（2D-HPLC-MS）中基于IPG胶条等电聚焦与MALDI-TOF-MS联用的方法，下列哪项正确？", "o": ["A. 用pH5.7~6.0的IPG胶条分离大肠杆菌总蛋白，可鉴定约250个蛋白质", "B. 该方法鉴定蛋白质数量少于传统2-DE", "C. 该方法不能测定蛋白质相对分子质量", "D. 该方法完全解决了胶上酶切和直接测序问题"], "a": "A", "e": "用pH5.7~6.0的IPG胶条分离大肠杆菌总蛋白，可鉴定约250个蛋白质，而传统2-DE仅约100个；对小于50 kDa的蛋白质，相对分子质量准确度达0.1%~0.2%。该方法省去从2-DE胶向质谱过渡的繁琐操作，但在胶上酶切和直接测序方面仍有问题。"}, "cards": [{"front": "基于IPG胶条等电聚焦与MALDI-TOF-MS联用的方法相比传统2-DE有何优势？", "back": "可鉴定约250个蛋白质，传统2-DE仅约100个；对小于50 kDa的蛋白质，相对分子质量准确度达0.1%~0.2%，pH准确度约±0.3；省去从2-DE胶向质谱过渡的繁琐操作。", "mnemonic": "IPG-IEF直接联用MALDI，省去“胶上挖点”的麻烦，鉴定数量翻倍。", "useImg": false}]}, {"i": 7, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "2D-HPLC-MS的优化、DIGE与ICAT技术", "notes": "本页继续讲二维色谱-质谱：为获得一个色谱图并减小死体积，采用细内径（0.127 mm）管路并尽量缩短管路长度。与2-DE/MS相比，2D-HPLC-MS的不足是蛋白质直接酶切得到的肽混合物过于复杂，较难实现细胞全部蛋白质的识别与鉴定；但经技术改进后，可作为2-DE的补充方法，成为大规模蛋白质分离与鉴定的有效策略。接着介绍荧光差异凝胶电泳（DIGE）：它是对2-DE的技术改进，结合多重荧光分析，在同一块胶上共同分离多个分别由不同荧光标记的样品，并首次引入内标概念。两种样品蛋白用不同荧光标记后混合进行2-DE，检测蛋白在两种样品中的表达差异，提高准确性、可靠性和可重复性；每个蛋白点有自己的内标，软件可全自动根据内标校准表达量，保证丰度变化真实。DIGE已应用于人、大鼠、小鼠、真菌、细菌等样品，主要用于功能蛋白质组学，如肿瘤研究、疾病分子标志物寻找、药物作用分子机制或毒理学研究。最后介绍同位素亲和标签（ICAT）技术：其关键是ICAT试剂，由三部分组成；中间为连接部分，分别连接8个氢原子或重氢原子，前者称轻链试剂，后者称重链试剂；一端连接特异反应基团，可与蛋白质中半胱氨酸的巯基连接以标记蛋白质，另一端连接生物素，用于标记蛋白质或多肽链。", "page": 163, "level": "掌握", "img": "assets/img/ch08/p163.jpg", "anim": null, "fig": null, "points": ["2D-HPLC-MS采用细内径（0.127 mm）管路并尽量缩短管路长度，以减小死体积", "2D-HPLC-MS不足：蛋白质直接酶切得到的肽混合物过于复杂，较难实现细胞全部蛋白质的识别与鉴定", "经技术改进后，2D-HPLC-MS可作为2-DE的补充方法，成为大规模蛋白质分离与鉴定的有效策略", "DIGE（荧光差异凝胶电泳）是对2-DE的改进", "ICAT技术用于蛋白质定量比较", "⚠️ 考点/易错点：易混技术：DIGE是2-DE的荧光多重标记改进，可在同一块胶上分离多个样本；2D-HPLC-MS不足是酶切肽混合物过复杂，常作为2-DE补充而非完全替代。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于2D-HPLC-MS的优化、DIGE与ICAT技术，下列哪项正确？", "o": ["A. 2D-HPLC-MS与2-DE/MS相比，其不足是蛋白质直接酶切得到的肽混合物过于复杂", "B. DIGE不是对2-DE的技术改进", "C. ICAT技术不能用于蛋白质定量", "D. 2D-HPLC-MS完全不能作为2-DE的补充方法"], "a": "A", "e": "2D-HPLC-MS的不足是蛋白质直接酶切得到的肽混合物过于复杂，较难实现细胞全部蛋白质的识别与鉴定；但经技术改进后，可作为2-DE的补充方法。DIGE是对2-DE的技术改进，结合多重荧光分析。"}, "cards": [{"front": "2D-HPLC-MS的不足是什么？如何弥补？", "back": "不足：蛋白质直接酶切得到的肽混合物过于复杂，较难实现细胞全部蛋白质的识别与鉴定。弥补：经技术改进后，可作为2-DE的补充方法，成为大规模蛋白质分离与鉴定的有效策略。", "mnemonic": "2D-HPLC-MS是“补充队员”，不是“主力前锋”；肽太复杂时还得靠2-DE帮忙。", "useImg": false}]}, {"i": 8, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "SELDI技术、方法比较与蛋白质芯片技术", "notes": "本页先总结SELDI技术：可先纯化，因此能分析复杂生物样品；可分析疏水性蛋白质、等电点过高或过低的蛋白质及低分子质量蛋白质（<25 kDa），还能发现未经处理样品中被掩盖的低丰度蛋白质，增加发现生物标志物的机会。SELDI只需少量样品，较短时间内可得结果，重复性好，适合临床诊断及大规模筛选疾病相关生物标志物；可直接检测不经处理的尿液、血液、脑脊液、关节腔滑液、支气管洗出液、细胞裂解液和各种分泌物等，从而获得目标蛋白质的分子质量、等电点、糖基化位点与磷酸化位点等信息。综合可见，不同蛋白质分离与鉴定方法各具特色，但均存在不足，技术将不断完善。随后介绍蛋白质芯片技术（protein microarrays）：一种高通量蛋白质功能分析技术，原理与DNA芯片（cDNA微阵列）类似，在固体支持物上采用高密度网格固定整个蛋白质组，从而对特定样品中的表达蛋白进行大规模分析。蛋白质芯片类型包括抗原芯片、抗体芯片，以及以蛋白质、底物或核苷酸为捕获基团的芯片；可用于蛋白质表达谱分析、研究蛋白质-蛋白质相互作用，甚至DNA/RNA-蛋白质及配体-蛋白质相互作用。在芯片上，特定蛋白质（如抗体）或配体固定在固体载体上，通过“免疫杂交”捕获样品中的蛋白质分子。但与DNA芯片相比，蛋白质芯片技术仍处于相对初期阶段，在蛋白质组水平上的芯片制作、自动检测及数据分析方面的发展远不如DNA芯片顺利；蛋白质的特点是相同的结构基序（structural motif）等。", "page": 164, "level": "理解", "img": "assets/img/ch08/p164.jpg", "anim": null, "fig": null, "points": ["SELDI可先纯化，能分析复杂生物样品", "SELDI可分析疏水性蛋白质、等电点过高或过低的蛋白质及低分子质量蛋白质（<25 kDa）", "SELDI能发现未经处理样品中被掩盖的低丰度蛋白质，增加发现生物标志物的机会", "SELDI只需少量样品，较短时间内可得结果，重复性好，适合临床诊断及大规模筛选疾病相关生物标志物", "SELDI可直接检测不经处理的尿液、血液、脑脊液、关节腔滑液等", "⚠️ 考点/易错点：SELDI可分析疏水性、等电点过高/过低及低分子质量（<25 kDa）蛋白质，并能发现被掩盖的低丰度蛋白；易考其可直接检测未经处理的尿液、血液等临床样品、适合大规模筛选生物标志物的特点。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于SELDI技术、方法比较与蛋白质芯片技术，下列哪项正确？", "o": ["A. SELDI不能分析疏水性蛋白质", "B. SELDI可分析低分子质量蛋白质（<25 kDa），并发现低丰度蛋白质", "C. SELDI需要大量样品且重复性差", "D. SELDI不能直接检测尿液、血液等临床样品"], "a": "B", "e": "SELDI可分析疏水性蛋白质、等电点过高或过低的蛋白质及低分子质量蛋白质（<25 kDa），还能发现未经处理样品中被掩盖的低丰度蛋白质。它只需少量样品，重复性好，可直接检测尿液、血液等多种样品。"}, "cards": [{"front": "SELDI技术有哪些优势和适用场景？", "back": "可先纯化，能分析复杂生物样品；可分析疏水性蛋白质、等电点过高或过低的蛋白质及低分子质量蛋白质（<25 kDa）；能发现低丰度蛋白质；只需少量样品，重复性好；适合临床诊断及大规模筛选疾病相关生物标志物。", "mnemonic": "SELDI是“临床侦察兵”：样品少、速度快、重复好，专找低丰度标志物。", "useImg": false}]}, {"i": 9, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "肽段鉴定数据库搜索与蛋白质翻译后修饰概述", "notes": "本页前半部分讲肽段鉴定的数据库搜索：由于蛋白质可能发生不完全水解，某些位点未断裂；且MALDI-MS得到的肽段带电荷，其质量与理论值略有偏差。因此搜索引擎必须在匹配肽段分子质量方面具有一定灵活性，以适应不完全水解及电荷修饰等情况。用户需提供尽可能详细的信息，如肽段指纹的分子质量、肽段序列、完整蛋白质的分子质量、等电点，甚至序列所属物种名等，这些对确定蛋白质唯一性非常重要。利用数据库匹配进行肽段鉴定遵循一个基本假设：被研究物种的所有蛋白质序列都是已知并存储于数据库中的。因此，该方法只在完全测序且基因组注释较完善的模式生物中应用较好，在非模式生物中应用非常有限。ExPASy（expert protein analysis system，http://www.expasy.org）由瑞士生物信息研究中心维护，是整合全面的蛋白质组学信息网络服务器，提供蛋白质序列、序列特征、结构、功能注释等信息与分析工具，其蛋白质组学工具中包含Mascot、ProFound等多种与质谱数据相关的肽段质量指纹数据分析工具。后半部分进入第三节“蛋白质的翻译后修饰”：蛋白质翻译合成后，需经过一些功能基团的共价修饰才能获得相应活性、结构与功能，这一生物学过程称为蛋白质翻译后修饰（posttranslational modification，PTM）。目前已知的PTM类型超过200种，常见类型包括磷酸化、糖基化、泛素化、乙酰化和硫酸盐化等。PTM通过改变分子大小、疏水性及蛋白质整体构象等影响蛋白质生物学功能的正常行使。", "page": 165, "level": "掌握", "img": "assets/img/ch08/p165.jpg", "anim": null, "fig": null, "points": ["蛋白质可能发生不完全水解，某些位点未断裂", "MALDI-MS得到的肽段带电荷，其质量与理论值略有偏差", "搜索引擎必须在匹配肽段分子质量方面具有一定灵活性，以适应不完全水解及电荷修饰等情况", "用户需提供尽可能详细的信息：肽段指纹的分子质量、肽段序列、完整蛋白质的分子质量、等电点、序列所属物种名等", "这些信息对确定蛋白质唯一性至关重要", "⚠️ 考点/易错点：肽段鉴定数据库搜索需在匹配肽段分子质量时具有一定灵活性，以适应不完全水解及电荷修饰导致的质量偏差；基本假设是被研究物种的所有蛋白质（序列）均已知并收录于数据库。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于肽段鉴定数据库搜索与蛋白质翻译后修饰概述，下列哪项正确？", "o": ["A. 搜索引擎匹配肽段分子质量时必须绝对精确，不能有任何灵活性", "B. 由于蛋白质可能不完全水解及肽段带电荷，搜索引擎需在匹配肽段分子质量方面具有一定灵活性", "C. 用户提供的信息越少越有利于确定蛋白质唯一性", "D. 数据库匹配鉴定肽段不依赖任何基本假设"], "a": "B", "e": "由于蛋白质可能发生不完全水解，某些位点未断裂；且MALDI-MS得到的肽段带电荷，其质量与理论值略有偏差。因此搜索引擎必须在匹配肽段分子质量方面具有一定灵活性。用户需提供尽可能详细的信息以确定蛋白质唯一性。"}, "cards": [{"front": "肽段鉴定数据库搜索时为什么需要灵活性？", "back": "因为蛋白质可能发生不完全水解，某些位点未断裂；且MALDI-MS得到的肽段带电荷，其质量与理论值略有偏差。搜索引擎必须在匹配肽段分子质量方面具有一定灵活性。", "mnemonic": "不完全水解+电荷偏差=质量对不上；搜索引擎要“宽容”一点。", "useImg": false}]}, {"i": 10, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "翻译后修饰的预测与质谱鉴定及蛋白质分选概述", "notes": "本页前半部分讲翻译后修饰预测：以特定激酶家族磷酸化位点预测为例，支持向量机采用已知激酶磷酸化位点的组成特征、周边序列组成特征等作为阳性集合，将不发生磷酸化的丝氨酸、苏氨酸、酪氨酸残基的周边序列组成特征作为阴性集合；模型经充足周围序列组成特征训练后，可较准确识别激酶中的磷酸化位点。翻译后修饰也可通过实验得到的质谱指纹数据进行鉴定。ExPASy和蛋白质组学服务工具页面列出很多根据质谱分子质量数据确定翻译后修饰的程序，可搜索序列中已知修饰位点，并在数据库片段匹配时根据修饰类型整合额外质量。例如FindMod可利用实验确定的肽段指纹信息比较实际测得肽段质量与理论值差异；若有差异，则利用预先确定的规则预测特定修饰类型。FindMod可预测28种不同类型修饰，包括甲基化、磷酸化、酯化和硫化等。GlyMod是另一种特异针对糖基化预测的程序，同样利用实验肽段与理论肽段的质量差异进行预测。后半部分进入第四节“蛋白质分选”：除线粒体和植物叶绿体可合成少量蛋白质外，绝大多数蛋白质均在细胞质基质中的核糖体上开始合成，然后运至细胞特定部位，这一过程称蛋白质分选（protein sorting），也称蛋白质定向转运（protein targeting）。正确的亚细胞定位是蛋白质行使功能不可缺少的一部分；很多蛋白质只有被转运到特定细胞位置才能行使功能，因此对蛋白质运输及亚细胞定位机制的研究已成为现代细胞生物学研究的主题。了解蛋白质细胞定位有助于缩小其可行使功能的范围，从而对蛋白质功能进行准确注释。", "page": 166, "level": "掌握", "img": "assets/img/ch08/p166.jpg", "anim": null, "fig": null, "points": ["支持向量机采用已知激酶磷酸化位点的组成特征、周边序列组成特征等作为阳性集合", "将不发生磷酸化的丝氨酸、苏氨酸、酪氨酸残基的周边序列组成特征作为阴性集合", "模型经充足周围序列组成特征训练后，可较准确识别激酶中的磷酸化位点", "翻译后修饰也可通过实验得到的质谱指纹数据进行鉴定", "ExPASy和蛋白质组学服务平台可用于翻译后修饰预测", "⚠️ 考点/易错点：翻译后修饰预测中，支持向量机以已知磷酸化位点序列特征为阳性集合、不发生磷酸化的Ser/Thr/Tyr周边序列为阴性集合训练模型；质谱指纹数据也可用于鉴定翻译后修饰。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于翻译后修饰的预测与质谱鉴定及蛋白质分选概述，下列哪项正确？", "o": ["A. 支持向量机预测磷酸化位点时，阳性集合为已知激酶磷酸化位点的组成特征和周边序列组成特征", "B. 翻译后修饰不能通过质谱指纹数据鉴定", "C. ExPASy不能用于确定翻译后修饰", "D. 蛋白质分选与翻译后修饰无关"], "a": "A", "e": "以特定激酶家族磷酸化位点预测为例，支持向量机采用已知激酶磷酸化位点的组成特征、周边序列组成特征等作为阳性集合，将不发生磷酸化的丝氨酸、苏氨酸、酪氨酸残基的周边序列组成特征作为阴性集合。翻译后修饰也可通过实验得到的质谱指纹数据进行鉴定。"}, "cards": [{"front": "支持向量机如何预测激酶磷酸化位点？", "back": "采用已知激酶磷酸化位点的组成特征、周边序列组成特征等作为阳性集合；将不发生磷酸化的丝氨酸、苏氨酸、酪氨酸残基的周边序列组成特征作为阴性集合；模型经充足训练后可较准确识别磷酸化位点。", "mnemonic": "阳性=已知磷酸化位点，阴性=不磷酸化位点；SVM学“周边序列长相”来预测。", "useImg": false}]}, {"i": 11, "sec": "第二节 蛋白质的大规模分离鉴定技术", "title": "蛋白质亚细胞定位预测方法", "notes": "本页继续讲蛋白质分选与亚细胞定位预测。核定位信号（NLS）通常由7~41个残基组成，与前几类信号不同，核定位信号位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序的(K/R)X(K/R)片段；核定位信号序列在蛋白质转运后不会被剪除。蛋白质亚细胞定位的计算预测方法可粗略分为两类。第一类主要利用蛋白质氨基酸序列中的信号特征（signal），同时还需要表达谱数据、系统发育图谱、数据库记录描述内容中的上下文及GO注释词条等额外信息。当提供上述额外信息时，预测准确性比单独基于序列的预测方法高很多，但这种额外数据可遇而不可求。因此，利用数据库内容上下文或GO词条进行预测时，需要相应蛋白质已具有一定的注释信息，这些注释信息中经常包含相应的亚细胞定位信息，它们或者明确出现在GO“细胞组分”（cellular component）相应词条中，或者在Swiss-Prot数据库记录的描述行或关键词行中给予提示。第二类方法只利用序列进行对库的同源性搜索，或查找与之共同出现（co-occurrence）的蛋白质结构域。如果查询蛋白质序列与已知亚细胞定位的蛋白质同源，可利用同源序列的性质进行注释转移，预测结果通常较准确，特别是两个同源序列相似性非常好时。如果找不到相近同源序列，则需要利用能对真实蛋白质分选信号序列进行统计性学习的方法（如机器学习中的神经网络、隐马尔可夫模型及支持向量机等）进行预测。SignalP（http://www.cbs.dtu.dk/services/SignalP/）是一个基于……（信号肽预测工具）。", "page": 167, "level": "理解", "img": "assets/img/ch08/p167.jpg", "anim": null, "fig": null, "points": ["核定位信号（NLS）通常由7~41个残基组成", "核定位信号位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序的(K/R)X(K/R)片段", "核定位信号序列在蛋白质转运后不会被剪除", "蛋白质亚细胞定位的计算预测方法可粗略分为两类", "第一类主要利用蛋白质氨基酸序列中的信号特征（signal），同时还需要表...", "⚠️ 考点/易错点：核定位信号（NLS）位于蛋白质序列内部，通常为1~2个含碱性残基的(K/R)X(K/R)片段，由7~41个残基组成，且转运后不被剪除——这是与信号肽等可剪除分选信号的易混点。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于蛋白质亚细胞定位预测方法，下列哪项正确？", "o": ["A. 核定位信号通常位于蛋白质序列内部，转运后不会被剪除", "B. 核定位信号通常位于N端，转运后被剪除", "C. 蛋白质亚细胞定位预测只能利用氨基酸序列信号，不能利用表达谱或GO注释", "D. 核定位信号不含碱性残基"], "a": "A", "e": "核定位信号（NLS）通常由7~41个残基组成，位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序的(K/R)X(K/R)片段；核定位信号序列在蛋白质转运后不会被剪除。亚细胞定位预测还可利用表达谱、系统发育图谱、数据库描述及GO注释等额外信息。"}, "cards": [{"front": "核定位信号（NLS）有什么特点？", "back": "通常由7~41个残基组成；位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序的(K/R)X(K/R)片段；在蛋白质转运后不会被剪除。", "mnemonic": "NLS是“内部通行证”：藏在序列里，用完不撕掉。", "useImg": false}]}, {"i": 12, "sec": "第五节 蛋白质相互作用", "title": "亚细胞定位预测工具与蛋白质相互作用概述", "notes": "本页首先承接亚细胞定位预测，介绍PSORT、WoLF PSORT和PSORTb v3.0。PSORT基于信号肽与已知定位信号肽数据库进行最近邻匹配，但只能预测动物和酵母的12种定位类型，且不能预测植物蛋白。WoLF PSORT是PSORT的扩展，通过分析分选信号、氨基酸组成及DNA结合基序等序列基序，将氨基酸序列转变为多种定位特征，再用K最近邻分类器预测定位，恢复了对植物蛋白的预测，对3个物种的定位类型均超过10种。PSORTb v3.0则针对细菌和古菌预测亚细胞定位，有在线和本地版本。随后进入第五节“蛋白质相互作用”。细胞中大部分功能由蛋白质执行，蛋白质间相互作用是细胞功能实现的基础。相互作用包括形成稳定复合物的强相互作用和瞬时的弱相互作用；参与形成复合物的蛋白质比仅瞬时相互作用的蛋白质表现出更紧密的表达共调控。研究蛋白质互作对探寻细胞信号转导途径、复杂蛋白质结构建模及理解生化过程均十分必要。实验鉴定互作主要包括遗传学、生物化学和生物物理方法。", "page": 168, "level": "掌握", "img": "assets/img/ch08/p168.jpg", "anim": null, "fig": null, "points": ["PSORT基于信号肽与已知定位信号肽数据库进行最近邻匹配", "PSORT只能预测动物和酵母的12种定位类型，且不能预测植物蛋白", "WoLF PSORT是PSORT的扩展，通过分析分选信号、氨基酸组成及DNA结合基序等序列基序", "WoLF PSORT将氨基酸序列转变为多种定位特征，再用K最近邻分类器预测定位", "PSORTb v3.0用于细菌蛋白质亚细胞定位预测", "⚠️ 考点/易错点：PSORT只能预测动物和酵母的12种定位类型且不能预测植物蛋白；WoLF PSORT通过序列基序转为定位特征并用K最近邻分类器预测，恢复了对植物蛋白的预测。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于亚细胞定位预测工具与蛋白质相互作用概述，下列哪项正确？", "o": ["A. PSORT只能预测动物和酵母的12种定位类型，且不能预测植物蛋白", "B. WoLF PSORT不能预测植物蛋白", "C. PSORTb v3.0只能预测动物蛋白", "D. WoLF PSORT不使用K最近邻分类器"], "a": "A", "e": "PSORT基于信号肽与已知定位信号肽数据库进行最近邻匹配，但只能预测动物和酵母的12种定位类型，且不能预测植物蛋白。WoLF PSORT是PSORT的扩展，通过分析分选信号、氨基酸组成及DNA结合基序等序列基序，将氨基酸序列转变为多种定位特征，再用K最近邻分类器预测定位，恢复了对植物蛋白的预测。"}, "cards": [{"front": "PSORT和WoLF PSORT有什么区别？", "back": "PSORT基于信号肽与已知定位信号肽数据库进行最近邻匹配，只能预测动物和酵母的12种定位类型，不能预测植物蛋白；WoLF PSORT是PSORT的扩展，通过分析分选信号、氨基酸组成及DNA结合基序等序列基序，将氨基酸序列转变为多种定位特征，再用K最近邻分类器预测定位。", "mnemonic": "PSORT是“基础版”，WoLF PSORT是“增强版”——加了氨基酸组成和DNA结合基序特征。", "useImg": false}]}, {"i": 13, "sec": "第五节 蛋白质相互作用", "title": "酵母双杂交系统及其局限与遗传学互作鉴定", "notes": "本页以图8-3展示酵母双杂交系统检测蛋白质互作。该系统将诱饵蛋白与DNA结合结构域（BD）融合，猎物蛋白与转录激活结构域（AD）融合；若诱饵与猎物互作，BD与AD靠近，激活报告基因转录。其灵敏度高，可检测微弱、瞬时的互作，但存在局限：第一，它不是直接检测互作的方法，某些蛋白质自身具有转录激活功能，使AD-猎物与BD-诱饵无需特异结合即可启动转录，产生假阳性；第二，对互作蛋白的细胞定位要求严格，只有定位于细胞核的互作才能激活报告基因，细胞质或细胞膜蛋白难以分析；第三，只能检测两个组分的互作，需要多个蛋白质共同参与的互作无法检测。与酵母双杂交相比，遗传学方法属于小规模互作实验，通过观察两个候选互作基因（X、Y）的突变体表型研究。抑制突变可恢复最初X基因突变导致的异常表型：X第一次突变改变蛋白质X构象，阻止其与Y互作，丧失功能；在Y基因上引入互补突变可重建互作，恢复表型。合成致死筛选则利用X和Y基因分别突变或双突变的致死效应来鉴定互作。", "page": 169, "level": "掌握", "img": "assets/img/ch08/p169.jpg", "anim": null, "fig": "看图8-3时，先找诱饵蛋白-BD融合体和猎物蛋白-AD融合体；若两者互作，BD与AD靠近激活报告基因转录，通过报告基因表达判断互作。注意区分假阳性和假阴性的来源。", "points": ["酵母双杂交系统将诱饵蛋白与DNA结合结构域（BD）融合，猎物蛋白与转录激活结构域（AD）融合", "若诱饵与猎物互作，BD与AD靠近，激活报告基因转录", "灵敏度高，可检测微弱、瞬时的互作", "局限一：不是直接检测互作的方法，某些蛋白质自身具有转录激活功能，产生假阳性", "局限二：部分蛋白质无法进入细胞核或正确折叠，产生假阴性", "⚠️ 考点/易错点：酵母双杂交灵敏度高可检测微弱、瞬时互作，但并非直接检测互作；易产生假阳性（某些蛋白自身具转录激活功能），且要求互作发生在细胞核内才能激活报告基因。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于酵母双杂交系统及其局限与遗传学互作鉴定，下列哪项正确？", "o": ["A. 酵母双杂交系统中诱饵蛋白与AD融合，猎物蛋白与BD融合", "B. 某些蛋白质自身具有转录激活功能，可导致假阳性", "C. 酵母双杂交系统只能检测强互作，不能检测微弱或瞬时互作", "D. 酵母双杂交系统对互作蛋白的细胞定位没有要求"], "a": "B", "e": "酵母双杂交系统将诱饵蛋白与DNA结合结构域（BD）融合，猎物蛋白与转录激活结构域（AD）融合。其灵敏度高，可检测微弱、瞬时的互作，但存在局限：某些蛋白质自身具有转录激活功能，使AD-猎物与BD-诱饵无需特异结合即可启动转录，产生假阳性；且只有定位于细胞核的互作才能激活报告基因。"}, "cards": [{"front": "酵母双杂交系统的基本原理是什么？", "back": "将诱饵蛋白与DNA结合结构域（BD）融合，猎物蛋白与转录激活结构域（AD）融合；若诱饵与猎物互作，BD与AD靠近，激活报告基因转录。", "mnemonic": "诱饵-BD + 猎物-AD = 靠近激活报告基因；不互作就不激活。", "useImg": false}, {"front": "酵母双杂交系统有哪些局限？", "back": "第一，不是直接检测互作的方法，某些蛋白质自身具有转录激活功能，产生假阳性；第二，部分蛋白质无法进入细胞核或正确折叠，产生假阴性。", "mnemonic": "假阳性=自激活，假阴性=进不了核/折不对。", "useImg": false}]}, {"i": 14, "sec": "第五节 蛋白质相互作用", "title": "亲和层析、免疫共沉淀与蛋白质芯片", "notes": "本页介绍生物化学亲和方法。GST pull-down：将诱饵蛋白与GST融合，固定在谷胱甘肽层析柱上，与GST融合蛋白互作的蛋白质被保留，无互作的被洗脱。优点是任一蛋白质都可与GST融合作为诱饵；但必须设置仅含GST的对照层析，以排除与GST本身互作的蛋白质。纯化后的互作蛋白可通过凝胶电泳和质谱鉴定。免疫共沉淀（Co-IP）利用抗体特异性结合蛋白质复合物中某一组分使复合物沉降。在保持互作的条件下制备细胞裂解液，加入针对蛋白质X的抗体，则X及与X互作的蛋白质被沉淀。优点是所研究的互作蛋白均为经翻译后修饰的天然蛋白，可表征生理条件下的互作；但需要制备针对目标蛋白的多克隆或单克隆抗体，过程复杂，且目标蛋白需达到一定浓度才能形成沉淀，只适用于高表达目标蛋白。亲和层析与免疫共沉淀的共同问题是可能分离出非直接互作的蛋白质，需用交联（cross-linking）确定直接互作并证实复合物空间架构。蛋白质芯片（protein chip/microarray）是高通量亲和技术，制备类似DNA微阵列，用机械手将少量液态样品点在玻片等固体基质上；捕获互作蛋白可在很大范围（如表面化学反应捕获所有相关蛋白）或很小甚至特异结合范围内进行。", "page": 170, "level": "掌握", "img": "assets/img/ch08/p170.jpg", "anim": null, "fig": null, "points": ["GST pull-down：将诱饵蛋白与GST融合，固定在谷胱甘肽层析柱上，与GST融合蛋白互作的蛋白质被保留", "GST pull-down必须设置仅含GST的对照层析，以排除与GST本身互作的蛋白质", "纯化后的互作蛋白可通过凝胶电泳和质谱鉴定", "免疫共沉淀（Co-IP）利用抗体特异性结合蛋白质复合物中某一蛋白质，从而沉淀整个复合物", "蛋白质芯片可高通量检测蛋白质相互作用", "⚠️ 考点/易错点：GST pull-down必须设置仅含GST的对照层析以排除与GST本身互作的蛋白；免疫共沉淀（Co-IP）利用抗体结合复合物中某一组分使复合物沉降，需在保持互作条件下制备裂解液。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于亲和层析、免疫共沉淀与蛋白质芯片，下列哪项正确？", "o": ["A. GST pull-down中必须设置仅含GST的对照层析，以排除与GST本身互作的蛋白质", "B. GST pull-down中不需要任何对照", "C. 免疫共沉淀不能用于研究蛋白质复合物", "D. 纯化后的互作蛋白不能用质谱鉴定"], "a": "A", "e": "GST pull-down将诱饵蛋白与GST融合，固定在谷胱甘肽层析柱上，与GST融合蛋白互作的蛋白质被保留。优点是任一蛋白质都可与GST融合作为诱饵；但必须设置仅含GST的对照层析，以排除与GST本身互作的蛋白质。纯化后的互作蛋白可通过凝胶电泳和质谱鉴定。"}, "cards": [{"front": "GST pull-down实验为什么必须设置仅含GST的对照层析？", "back": "为了排除与GST本身互作的蛋白质，避免假阳性结果。", "mnemonic": "GST是“鱼钩”，对照就是“空钩”——看有没有鱼自己咬空钩。", "useImg": false}]}, {"i": 15, "sec": "第五节 蛋白质相互作用", "title": "基于基因次序与基因/结构域融合的互作预测", "notes": "本页继续介绍基于基因组信息的互作预测。基因次序（基因邻近）关系在物种演化中具有一定保守性，可作为基因产物间功能关系的指示，支持大多数原核生物基因组的互作蛋白预测；但对真核基因组，基因次序预测不如基因表达共调控有说服力。重点介绍基于基因/结构域融合事件的预测。理论基础：某物种中一个蛋白质家族包含融合结构域AB，而其他物种中常存在相互分离的两个基因A’和B’；这类蛋白称为“复合”蛋白（融合蛋白），其每个结构域称为“成分”蛋白。预测主要在具有完整基因组序列的物种中鉴定基因融合事件，以发现不同物种中对应的同源蛋白。若一个“复合”蛋白特定地与另一物种中两个“成分”蛋白相似，即使这两个成分蛋白的编码基因不相邻，它们也很可能发生相互作用以执行与AB相同的功能（图8-4）。反之，若两个祖先基因A和B融合，在其他基因组中这两个基因很可能融合在一起。进一步解释：当两个成分蛋白作为结构域在一个蛋白质中融合时，它们必须位置非常接近以执行同样功能；若存在于两个不同蛋白质中，为维持相同功能，其相互靠近及相互作用的特性也必须维持。因此研究基因/蛋白质融合事件可预测蛋白质-蛋白质相互作用，这种方法称为“Rosetta stone”方法。", "page": 171, "level": "掌握", "img": "assets/img/ch08/p171.jpg", "anim": null, "fig": null, "points": ["基因次序（基因邻近）关系在物种演化中具有一定保守性，可作为基因产物间功能关系的指示", "基因次序预测支持大多数原核生物基因组的互作蛋白预测", "对真核基因组，基因次序预测不如基因表达共调控有说服力", "基于基因/结构域融合事件的预测：某物种中一个蛋白质家族包含融合结构域AB，其他物种中常存在相互分离的两个基因A'和B'", "融合事件暗示A和B在功能上相关或发生互作", "⚠️ 考点/易错点：基因次序（基因邻近）预测在原核生物中支持度较高，但对真核基因组不如基因表达共调控有说服力；基因/结构域融合预测基于某物种融合蛋白AB与其他物种分离的A'、B'基因的对应关系。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于基于基因次序与基因/结构域融合的互作预测，下列哪项正确？", "o": ["A. 基因次序关系对真核基因组预测比基因表达共调控更有说服力", "B. 基因次序关系在物种演化中具有一定保守性，可作为基因产物间功能关系的指示", "C. 基因/结构域融合预测中，融合蛋白的每个结构域称为“复合”蛋白", "D. 基因融合事件与蛋白质互作预测无关"], "a": "B", "e": "基因次序（基因邻近）关系在物种演化中具有一定保守性，可作为基因产物间功能关系的指示，支持大多数原核生物基因组的互作蛋白预测；但对真核基因组，基因次序预测不如基因表达共调控有说服力。基因/结构域融合预测中，包含融合结构域AB的蛋白称为“复合”蛋白，其每个结构域称为“成分”蛋白。"}, "cards": [{"front": "基于基因/结构域融合事件预测互作的原理是什么？", "back": "某物种中一个蛋白质家族包含融合结构域AB，而其他物种中常存在相互分离的两个基因A'和B'；融合事件暗示A和B在功能上相关或发生互作。", "mnemonic": "“合久必分，分久必合”——融合在一起说明它们本来就是一伙的。", "useImg": false}]}, {"i": 16, "sec": "第五节 蛋白质相互作用", "title": "系统发育谱与镜像树预测互作蛋白", "notes": "本页以图8-5说明系统发育谱（phylogenetic profile）预测互作蛋白。关注7个蛋白质P1–P7，在大肠杆菌（EC）、酿酒酵母（SC）、流感嗜血杆菌（HI）和枯草杆菌（BS）4个完全测序基因组中，针对大肠杆菌每个蛋白质序列构建系统发育谱，表明哪些基因组编码其同源物。将系统发育谱聚类，找到相同或相似谱型的蛋白质。P2与P7、P3与P6具有一致谱型，因此可能功能相关（存在于同一途径或同一蛋白质复合物中）；用直线相连的谱型间有一定差异，称为邻居（neighbor）。随后介绍镜像树（mirror tree）方法，这是一种基于系统发育分析的更定量化互作预测方法。观察发现，互作蛋白的进化距离相似性水平显著高于无互作关系的蛋白质，表明互作蛋白受功能约束，进化过程应保持一致。若突变发生在其中一个蛋白质中，为维持相互作用，相应突变很可能也发生在其互作伴侣上，结果两个互作蛋白具有反映相似进化历史的进化树形，即呈现共同进化特征。通过构建和比较它们的系统发育树可预测互作。", "page": 172, "level": "掌握", "img": "assets/img/ch08/p172.jpg", "anim": null, "fig": "看图8-5时，关注7个蛋白质P1–P7在4个完全测序基因组（EC、SC、HI、BS）中的同源物分布；将系统发育谱聚类，谱型相同或相似的蛋白质（如P2与P7、P3与P6）提示可能互作。", "points": ["系统发育谱（phylogenetic profile）预测互作蛋白：针对大肠杆菌每个蛋白质序列构建系统发育谱", "系统发育谱表明哪些基因组编码其同源物", "将系统发育谱聚类，找到相同或相似谱型的蛋白质", "P2与P7、P3与P6具有一致谱型，提示它们可能互作", "系统发育谱方法基于共同进化关系预测功能关联", "⚠️ 考点/易错点：系统发育谱预测互作的核心是：谱型相同或相似的蛋白质可能功能相关；易错点是谱型一致只提示功能相关（同一途径/复合物），并不等于直接物理互作。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于系统发育谱与镜像树预测互作蛋白，下列哪项正确？", "o": ["A. 系统发育谱中，具有相同或相似谱型的蛋白质可能功能相关", "B. 系统发育谱中，谱型不同才说明功能相关", "C. 镜像树方法中，相关系数r≥0.8说明两个蛋白质不可能互作", "D. 系统发育谱只能用于真核生物"], "a": "A", "e": "系统发育谱通过比较不同基因组中蛋白质同源物的存在情况，将系统发育谱聚类，找到相同或相似谱型的蛋白质，这些蛋白质可能功能相关，存在于同一途径或同一蛋白质复合物中。"}, "cards": [{"front": "系统发育谱如何预测互作蛋白？", "back": "针对目标物种每个蛋白质序列构建系统发育谱，表明哪些基因组编码其同源物；将系统发育谱聚类，找到相同或相似谱型的蛋白质，提示它们可能互作。", "mnemonic": "“同进退”=谱型一致=可能互作；P2与P7、P3与P6就是例子。", "useImg": false}]}, {"i": 17, "sec": "第五节 蛋白质相互作用", "title": "镜像树关联分析、interologs及预测方法前提", "notes": "本页继续镜像树方法：计算两个蛋白质家族系统发育树的进化距离矩阵，若相关系数r≥0.8，则很可能两个蛋白质发生互作；当两个家族用于构建系统发育树的进化距离矩阵出现很强统计学相关性，且两个树型拓扑结构基本一致（形成类似镜像），即可确定两个蛋白质的功能相关性。图8-6展示利用镜像树预测互作蛋白：蛋白家族1与蛋白家族2分别构建系统发育树，通过关联分析比较树型。随后介绍基于序列同源性的互作预测。已知的蛋白质互作图谱能为新测序基因组的互作预测提供信息：若某基因组中一对蛋白质互作，则它们在另一基因组中的同源蛋白也可能发生类似互作，这种同源蛋白对称为互作物（interologs）。该方法依赖确定正确的直系同源蛋白并利用现有互作数据库。例如在新测序基因组中通过系统相似性搜索鉴定已知互作蛋白对可能的直系同源蛋白对，从中确定潜在保守互作。若互作蛋白具有已知三维结构，该方法还能帮助蛋白质四级结构建模。最后指出，前面各种预测方法都需要依赖某种特定前提。", "page": 173, "level": "理解", "img": "assets/img/ch08/p173.jpg", "anim": null, "fig": "看图8-6时，先分别构建蛋白家族1和蛋白家族2的系统发育树；再通过关联分析比较两棵树的拓扑结构，若树型基本一致（类似镜像）且相关系数r≥0.8，则提示两个蛋白质可能互作。", "points": ["镜像树方法：计算两个蛋白质家族系统发育树的进化距离矩阵", "若相关系数r≥0.8，则很可能两个蛋白质发生互作", "当两个家族进化距离矩阵出现很强统计学相关性，且两个树型拓扑结构基本一致（形成类似镜像），即可确定功能相关性", "interologs：基于模式生物中已知互作推断其他物种中的互作", "预测方法前提：互作蛋白质在进化过程中共同进化", "⚠️ 考点/易错点：镜像树法判定互作的关键阈值是两家族进化距离矩阵相关系数r≥0.8且树型拓扑基本一致；易混点是镜像树反映的是功能相关性/共进化，而非直接证明物理结合。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于镜像树关联分析、interologs及预测方法前提，下列哪项正确？", "o": ["A. 镜像树方法中，若两个蛋白质家族系统发育树的进化距离矩阵相关系数r≥0.8，则很可能发生互作", "B. 镜像树方法要求两个树型拓扑结构完全不同", "C. 基于序列同源性的互作预测不需要已知互作图谱", "D. interologs指同一物种内完全相同的蛋白质"], "a": "A", "e": "镜像树方法计算两个蛋白质家族系统发育树的进化距离矩阵，若相关系数r≥0.8，则很可能两个蛋白质发生互作；当两个家族用于构建系统发育树的进化距离矩阵出现很强统计学相关性，且两个树型拓扑结构基本一致，即可确定两个蛋白质的功能相关性。"}, "cards": [{"front": "镜像树方法预测互作蛋白的判断标准是什么？", "back": "计算两个蛋白质家族系统发育树的进化距离矩阵，若相关系数r≥0.8，且两个树型拓扑结构基本一致（形成类似镜像），则很可能两个蛋白质发生互作。", "mnemonic": "r≥0.8 + 树型镜像 = 互作；两棵树“照镜子”就是好搭档。", "useImg": false}]}, {"i": 18, "sec": "第五节 蛋白质相互作用", "title": "STRING数据库与蛋白质相互作用预测及习题", "notes": "本页属于第五节蛋白质相互作用。首先说明蛋白质相互作用证据包括直接互作与间接互作：直接互作指蛋白质之间发生物理互作；间接互作指功能相关，例如同一代谢途径中拥有相同底物的酶类，或同一遗传途径中具有调控关系的蛋白质。STRING8 收录了来源于630个基因组的250万个蛋白质的相关信息。使用STRING进行预测时，查询序列先根据COG（cluster of orthologous group，直系同源群）信息进行直系同源物分组，再在数据库中搜索已知的保守基因连锁模式（邻接基因）、基因融合情况及系统发育谱。STRING利用权重记分系统评估各基因组中3种类型蛋白质相关的显著性，并结合实验互作数据和文献挖掘信息。为降低假阳性并提高可信度，3种计算类型的相关蛋白质还会在内部参考数据集中再次检查。最终返回互作和功能相关蛋白质列表，对每个功能相关蛋白质提供计算预测、实验获得及文献挖掘证据，以及一个简单的蛋白质互作功能相关性分数。根据参与的多个功能相关伙伴情况，STRING还能以交互形式提供图形化显示的蛋白质结合互作网络及特定详细信息。页末列出复习题：蛋白质组与蛋白质组学定义；二维凝胶电泳分离蛋白质的局限性及液相色谱的优越性；蛋白质功能是否随时间、生理状态或条件变化；线粒体、叶绿体及细胞核定向转运信号肽的序列特征；鉴定蛋白质物理互作的实验方法；各类蛋白质互作预测方法的思想基础。并给出参考文献 Abbott A. 2001。", "page": 174, "level": "掌握", "img": "assets/img/ch08/p174.jpg", "anim": null, "fig": null, "points": ["直接互作：蛋白质之间发生物理互作", "间接互作：功能相关，例如同一代谢途径中拥有相同底物的酶类，或同一遗传途径中具有调控关系的蛋白质", "STRING8收录了来源于630个基因组的250万个蛋白质的相关信息", "使用STRING进行预测时，查询序列先根据COG（cluster of orthologous groups）进行注释", "蛋白质相互作用证据包括直接互作与间接互作", "⚠️ 考点/易错点：直接互作是物理互作，间接互作是功能相关（如同一代谢途径或调控关系）；STRING预测时先按COG做直系同源分组再检索，易错点是把功能相关误判为直接互作。"], "code": null, "lang": null, "principle": null, "formula": null, "check": {"q": "关于STRING数据库与蛋白质相互作用预测，下列哪项正确？", "o": ["A. 直接互作指蛋白质之间发生物理互作，间接互作指功能相关", "B. 间接互作仅指蛋白质之间发生物理结合", "C. STRING8只收录了一个基因组的信息", "D. 使用STRING预测时，查询序列不进行直系同源物分组"], "a": "A", "e": "蛋白质相互作用证据包括直接互作与间接互作：直接互作指蛋白质之间发生物理互作；间接互作指功能相关，例如同一代谢途径中拥有相同底物的酶类，或同一遗传途径中具有调控关系的蛋白质。STRING8收录了来源于630个基因组的250万个蛋白质的相关信息，查询序列先根据COG信息进行直系同源物分组。"}, "cards": [{"front": "直接互作和间接互作有什么区别？", "back": "直接互作指蛋白质之间发生物理互作；间接互作指功能相关，例如同一代谢途径中拥有相同底物的酶类，或同一遗传途径中具有调控关系的蛋白质。", "mnemonic": "直接=手拉手，间接=同一战壕的战友。", "useImg": false}]}], "mcq": [{"id": "ch08_mcq_1", "mod": "第八章 蛋白质组学", "modI": 0, "q": "蛋白质组（proteome）的准确定义是？", "o": ["A. 一个生物体所有基因的集合", "B. 一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质", "C. 一个细胞中所有mRNA的集合", "D. 一个蛋白质的所有翻译后修饰形式"], "a": "B", "e": "蛋白质组指一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质，与基因组相对应。A为基因组，C为转录组，D为蛋白质修饰组。", "kp": "ch08_s0_0"}, {"id": "ch08_mcq_2", "mod": "第八章 蛋白质组学", "modI": 0, "q": "二维凝胶电泳（2-DE）分离蛋白质的两个维度依次是？", "o": ["A. 分子质量、等电点", "B. 等电点、分子质量", "C. 疏水性、分子质量", "D. 电荷、疏水性"], "a": "B", "e": "2-DE第一向为等电聚焦（按等电点），第二向为SDS-PAGE（按分子质量）。", "kp": "ch08_s0_4"}, {"id": "ch08_mcq_3", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于MALDI和ESI两种软电离技术，下列说法正确的是？", "o": ["A. MALDI适合与液相色谱联用分析复杂样品", "B. ESI在激光脉冲激发下使样品从基质晶体中挥发并离子化", "C. MALDI常与TOF联用分析肽段精确质量，ESI常与离子阱或三重四极杆联用获取碎片信息", "D. ESI只能分析简单肽混合物"], "a": "C", "e": "MALDI在激光脉冲下使样品从基质晶体挥发离子化，常与TOF联用；ESI使分析物从溶液相电离，适合与液相分离联用，常与离子阱或三重四极杆联用，通过CID获取碎片信息。", "kp": "ch08_s0_8"}, {"id": "ch08_mcq_4", "mod": "第八章 蛋白质组学", "modI": 0, "q": "下列哪种质量分析器具有高灵敏度、宽动态范围、高分辨率和高精度，并可进行多元串联质谱？", "o": ["A. 离子阱（IT）", "B. 飞行时间（TOF）", "C. 四极杆（quadrupole）", "D. 傅里叶变换离子回旋共振（FTICR）"], "a": "D", "e": "FTICR-MS具有高灵敏度、宽动态范围、高分辨率和高精度，可同时选择几个母离子解离，进行多元串联质谱；离子阱灵敏度高但质量精度较低。", "kp": "ch08_s0_5"}, {"id": "ch08_mcq_5", "mod": "第八章 蛋白质组学", "modI": 0, "q": "蛋白质翻译后修饰（PTM）的常见类型不包括？", "o": ["A. 磷酸化", "B. 糖基化", "C. 泛素化", "D. 甲基化", "E. 以上都是常见类型"], "a": "E", "e": "常见PTM包括磷酸化、糖基化、泛素化、乙酰化、硫酸盐化、甲基化等，已知类型超过200种。", "kp": "ch08_s0_9"}, {"id": "ch08_mcq_6", "mod": "第八章 蛋白质组学", "modI": 0, "q": "在基于序列的翻译后修饰预测中，仅使用短序列基序（如[ST]-x-[RK]）容易产生什么问题？", "o": ["A. 假阴性过多", "B. 假阳性过多", "C. 无法识别修饰位点", "D. 计算速度过慢"], "a": "B", "e": "短序列基序几乎在每个蛋白质序列中出现多次，仅根据这一特征预测，大多数情况下会得到假阳性结果。需结合周边环境序列特征和统计学方法（如SVM）减少假阳性。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_7", "mod": "第八章 蛋白质组学", "modI": 0, "q": "支持向量机（SVM）在翻译后修饰预测中的基本思想是？", "o": ["A. 将修饰位点预测转化为分类问题，用最佳超平面区分真实信号与噪声", "B. 通过序列比对寻找同源蛋白", "C. 利用隐马尔可夫模型区分信号肽", "D. 通过质谱峰强度直接定量"], "a": "A", "e": "SVM将数据映射到多维空间，利用线性或非线性函数形成最佳超平面，将真实信号与噪声区别，即把修饰位点预测转化为分类问题（是或不是修饰位点）。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_8", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于蛋白质分选信号，下列说法错误的是？", "o": ["A. 线粒体定向转运肽位于N端，富含正电荷残基，缺少负电荷残基", "B. 叶绿体定位信号位于N端，其转运信号是双向的", "C. 核定位信号位于蛋白质内部，转运后不被剪除", "D. 所有分选信号在转运完成后都会被蛋白酶剪除"], "a": "D", "e": "核定位信号在蛋白质转运后并不会被剪除，而线粒体和叶绿体信号序列通常会被剪除。因此D错误。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_9", "mod": "第八章 蛋白质组学", "modI": 0, "q": "酵母双杂交（Y2H）系统的局限性不包括？", "o": ["A. 某些蛋白质自身转录激活功能可产生假阳性", "B. 要求互作蛋白定位于细胞核内", "C. 只能检测两个组分的互作", "D. 灵敏度太低，无法检测微弱或瞬间互作"], "a": "D", "e": "Y2H灵敏度非常高，能检测微弱、瞬间的互作。其局限包括假阳性、核内定位要求、只能检测双组分互作等。", "kp": "ch08_s0_13"}, {"id": "ch08_mcq_10", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于SignalP和WoLF PSORT，下列说法正确的是？", "o": ["A. SignalP仅使用神经网络，不包含隐马尔可夫模型", "B. WoLF PSORT利用K最近相邻分类法预测定位，恢复了对植物蛋白的预测", "C. PSORT能预测植物蛋白亚细胞定位，且对动物及酵母可给出超过20种类型", "D. SignalP只收集了真核生物一个训练数据集"], "a": "B", "e": "WoLF PSORT是PSORT的扩展版本，利用K最近相邻分类法预测定位，恢复了对植物蛋白的预测。SignalP从第二版起加入HMM，收集了3个不同物种训练数据集；PSORT不能预测植物蛋白，对动物及酵母只能给出12种类型。", "kp": "ch08_s0_12"}], "judge": [{"id": "ch08_judge_1", "modI": 0, "q": "蛋白质组是静态的，不随细胞类型、时间、空间和生理状态变化。", "a": "错", "e": "蛋白质组是动态的，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组。", "kp": "ch08_s0_3"}, {"id": "ch08_judge_2", "modI": 0, "q": "二维凝胶电泳（2-DE）第一向按分子质量分离，第二向按等电点分离。", "a": "错", "e": "2-DE第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）。", "kp": "ch08_s0_4"}, {"id": "ch08_judge_3", "modI": 0, "q": "MALDI常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。", "a": "对", "e": "MALDI在激光脉冲激发下使样品从基质晶体中挥发并离子化，适合分析简单肽混合物，常与TOF联用。", "kp": "ch08_s0_5"}, {"id": "ch08_judge_4", "modI": 0, "q": "ESI适合与液相分离手段联用，LC-MS适合复杂样品分析。", "a": "对", "e": "ESI使分析物从溶液相中电离，适合与液相色谱、毛细管电泳等联用，LC-MS适合复杂样品分析。", "kp": "ch08_s0_6"}, {"id": "ch08_judge_5", "modI": 0, "q": "支持向量机（SVM）是一种数据分类方法，将数据映射到多维空间，用最佳超平面区分真实信号与噪声。", "a": "对", "e": "SVM将修饰位点预测转化为分类问题，用已知阳性集和阴性集训练模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_6", "modI": 0, "q": "线粒体定向转运肽位于蛋白质C端，典型长度20~80个残基。", "a": "错", "e": "线粒体定向转运肽位于蛋白质N端，典型长度20~80个残基，富含精氨酸等带正电荷残基及丝氨酸、苏氨酸等带羟基残基。", "kp": "ch08_s0_18"}, {"id": "ch08_judge_7", "modI": 0, "q": "核定位信号位于蛋白质序列内部，转运后不被剪除。", "a": "对", "e": "核定位信号通常是一个或两个包含碱性残基及一致性基序K(K/R)X(K/R)的片段，转运后不被剪除。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_8", "modI": 0, "q": "SignalP最早使用神经网络进行蛋白质分选信号预测，从第二版起加入隐马尔可夫模型提高准确性。", "a": "对", "e": "SignalP是基于网络的亚细胞定位信号预测程序，神经网络算法包含识别信号肽打分和蛋白酶断裂位点打分；HMM用于区分信号肽及N端跨膜锚定片段。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_9", "modI": 0, "q": "酵母双杂交系统（Y2H）是直接检测蛋白质互作的方法，能检测多蛋白复合物。", "a": "错", "e": "Y2H不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_13"}, {"id": "ch08_judge_10", "modI": 0, "q": "遗传学方法可推断蛋白质互作但不能提供直接证明。", "a": "对", "e": "遗传学方法属于小规模蛋白质互作实验，通过观察两个互作候选基因的突变体表型研究，可推断互作但不能提供直接证明；亲和层析等物理方法为互作提供直接证据。", "kp": "ch08_s0_13"}], "fill": [{"id": "ch08_fill_1", "modI": 0, "q": "蛋白质组学是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及________。", "a": "相互作用", "kp": "ch08_s0_0"}, {"id": "ch08_fill_2", "modI": 0, "q": "二维凝胶电泳（2-DE）由Farrell于1975年提出，第一向按________分离，第二向按分子质量分离。", "a": "等电点", "kp": "ch08_s0_4"}, {"id": "ch08_fill_3", "modI": 0, "q": "MALDI常与________质量分析器联用，分析肽段精确质量。", "a": "飞行时间（TOF）", "kp": "ch08_s0_5"}, {"id": "ch08_fill_4", "modI": 0, "q": "ESI常与离子阱或________质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "a": "三重四极杆", "kp": "ch08_s0_5"}, {"id": "ch08_fill_5", "modI": 0, "q": "支持向量机（SVM）是一种数据分类方法，将数据映射到多维空间，用最佳________区分真实信号与噪声。", "a": "超平面", "kp": "ch08_s0_11"}, {"id": "ch08_fill_6", "modI": 0, "q": "线粒体定向转运肽位于蛋白质N端，典型长度20~80个残基，富含精氨酸等带正电荷残基及丝氨酸、苏氨酸等带羟基残基，缺少带________残基。", "a": "负电荷", "kp": "ch08_s0_10"}, {"id": "ch08_fill_7", "modI": 0, "q": "核定位信号位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序________的片段，转运后不被剪除。", "a": "K(K/R)X(K/R)", "kp": "ch08_s0_11"}, {"id": "ch08_fill_8", "modI": 0, "q": "酵母双杂交系统中，人为将转录因子的DNA结合结构域（BD）和转录激活结构域（AD）分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和________。", "a": "猎物蛋白（prey）", "kp": "ch08_s0_13"}], "short": [{"id": "ch08_short_1", "modI": 0, "q": "简述蛋白质组与蛋白质组学的定义及核心思想。", "a": "蛋白质组指一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质；蛋白质组学则是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及相互作用。核心思想是全局性研究，而非单个蛋白质。蛋白质组是动态的，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组。蛋白质数目通常远大于基因数目，因基因剪接和翻译后修饰所致。", "kp": "ch08_s0_0"}, {"id": "ch08_short_2", "modI": 0, "q": "简述二维凝胶电泳（2-DE）的原理及优缺点。", "a": "原理：第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）。优点：一次可分离几千个蛋白质；采用固相pH梯度干胶条（IPG）可提高分辨率和重复性。缺点：对膜蛋白、碱性蛋白、低丰度蛋白分离检测仍存在不足，且重复性、规模化、自动化受限。", "kp": "ch08_s0_4"}, {"id": "ch08_short_3", "modI": 0, "q": "简述MALDI和ESI两种软电离技术的特点及适用场景。", "a": "MALDI：在激光脉冲激发下使样品从基质晶体中挥发并离子化；适合分析简单肽混合物；常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。ESI：使分析物从溶液相中电离；适合与液相分离手段（如液相色谱、毛细管电泳）联用；LC-MS适合复杂样品分析；常与离子阱或三重四极杆质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "kp": "ch08_s0_8"}, {"id": "ch08_short_4", "modI": 0, "q": "简述基于序列的翻译后修饰预测中支持向量机（SVM）的应用。", "a": "发生PTM的底物蛋白质具有被特定修饰酶识别的序列基序，通常仅含5个残基，倾向存在于无固定三维结构的非球形区域，区域内多为极性、小或骨架柔韧的残基，便于修饰酶接近。但仅考虑短序列基序易产生大量假阳性，如磷酸化位点一致性序列[ST]-x-[RK]几乎在每个蛋白质中出现多次。为减少假阳性，需考虑修饰位点周边环境序列特点，并利用统计学方法。SVM将数据映射到多维空间，用最佳超平面区分真实信号与噪声，即将修饰位点预测转化为分类问题（是或不是）。以激酶磷酸化位点预测为例，用已知阳性集和阴性集训练SVM模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_10"}, {"id": "ch08_short_5", "modI": 0, "q": "简述酵母双杂交系统（Y2H）的原理及局限性。", "a": "原理：采用必须依赖转录因子才能激活的报告基因表达体系。转录因子同时具有DNA结合结构域（BD）和转录激活结构域（AD），人为将这两个结构域分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和猎物蛋白（prey）。当诱饵和猎物发生互作结合时，转录因子的两个结构域也结合并行使功能，导致报告基因表达。还可利用cDNA文库筛选与诱饵蛋白互作的蛋白质。局限性：不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_13"}], "calc": [{"id": "ch08_calc_1", "modI": 0, "q": "论述蛋白质组学的研究内容与意义，并说明其与基因组学的关系。", "a": "蛋白质组学不仅包括对表达蛋白的大规模鉴定和定量分析，还包括对蛋白质功能、细胞定位、修饰以及蛋白质相互作用的确定。中心法则指出信息流从DNA到蛋白质，DNA编码的蛋白质序列决定三维结构，结构决定功能。基因组计划的最终目的是确定基因组如何通过蛋白质实现生命活动。因此，蛋白质组学是连接基因组信息与生物功能的桥梁。本章主要讲述如何利用生物信息学方法进行蛋白质表达、翻译后修饰、定位及相互作用分析。", "steps": "1. 蛋白质组学定义与内容；2. 中心法则与结构功能关系；3. 基因组计划目的；4. 蛋白质组学作为桥梁；5. 生物信息学方法应用。", "kp": "ch08_s0_3"}, {"id": "ch08_calc_2", "modI": 0, "q": "论述蛋白质亚细胞定位的计算预测方法及其优缺点。", "a": "亚细胞定位计算预测方法可分两类。第一类利用蛋白质氨基酸序列中的信号特征，同时需要表达谱数据、系统发育图谱、数据库记录描述内容中的上下文及GO注释词条等额外信息；提供额外信息时准确性比单独基于序列的预测高很多，但额外数据可遇不可求。第二类只利用序列进行同源性搜索或查找共出现的蛋白质结构域；若查询序列与已知亚细胞定位蛋白质同源，可利用同源序列性质进行注释转移，预测较准确，尤其相似性非常好时；若找不到相近同源序列，则需利用机器学习方法（如神经网络、隐马尔可夫模型、支持向量机）对真实分选信号序列进行统计学习。", "steps": "1. 第一类方法：利用信号特征+额外信息；2. 优点：准确性高；3. 缺点：额外数据难获取；4. 第二类方法：仅利用序列；5. 同源搜索与注释转移；6. 机器学习方法应用。", "kp": "ch08_s0_11"}], "term": [{"id": "ch08_term_1", "modI": 0, "term": "Proteome", "def": "一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质；具有动态性，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组；蛋白质数目通常远大于基因数目，因基因剪接和翻译后修饰所致。", "kp": "ch08_s0_17"}, {"id": "ch08_term_2", "modI": 0, "term": "Proteomics", "def": "对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及相互作用；由Marc Wilkins等于20世纪90年代初提出；核心思想是全局性研究，而非单个蛋白质；是功能基因组学的核心和连接基因组信息与生物功能的桥梁。", "kp": "ch08_s0_0"}, {"id": "ch08_term_3", "modI": 0, "term": "Two-dimensional gel electrophoresis (2-DE)", "def": "由Farrell于1975年提出；第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）；一次可分离几千个蛋白质；采用固相pH梯度干胶条（IPG）可提高分辨率和重复性；但对膜蛋白、碱性蛋白、低丰度蛋白分离检测仍存在不足，且重复性、规模化、自动化受限。", "kp": "ch08_s0_9"}, {"id": "ch08_term_4", "modI": 0, "term": "MALDI", "def": "基质辅助激光解吸电离；在激光脉冲激发下使样品从基质晶体中挥发并离子化；适合分析简单肽混合物；常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。", "kp": "ch08_s0_8"}, {"id": "ch08_term_5", "modI": 0, "term": "ESI", "def": "电喷雾电离；使分析物从溶液相中电离；适合与液相分离手段（如液相色谱、毛细管电泳）联用；LC-MS适合复杂样品分析；常与离子阱或三重四极杆质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "kp": "ch08_s0_5"}, {"id": "ch08_term_6", "modI": 0, "term": "FTICR-MS", "def": "傅里叶变换离子回旋共振质谱；具有高灵敏度、宽动态范围、高分辨率和高精度（质量准确度可小于mg/L）；可一次分析数百个完整蛋白质分子；具备多元串联质谱能力，可同时选择几个母离子解离，提高通量；但操作复杂、肽段断裂效率低、价格昂贵。", "kp": "ch08_s0_7"}, {"id": "ch08_term_7", "modI": 0, "term": "Post-translational modification (PTM)", "def": "蛋白质翻译合成后，需经过功能基团的共价修饰才能获得相应活性、结构与功能；已知PTM类型超过200种，常见包括磷酸化、糖基化、泛素化、乙酰化和硫酸盐化等；通过改变分子大小、疏水性及整体构象影响蛋白质生物学功能；可直接影响到蛋白质间相互作用以及蛋白质在不同亚细胞区域的分布。", "kp": "ch08_s0_9"}, {"id": "ch08_term_8", "modI": 0, "term": "Support vector machine (SVM)", "def": "一种数据分类方法；将数据映射到多维空间，用最佳超平面区分真实信号与噪声；将修饰位点预测转化为分类问题（是或不是）；以激酶磷酸化位点预测为例，用已知阳性集和阴性集训练SVM模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_9"}, {"id": "ch08_term_9", "modI": 0, "term": "Protein sorting / protein targeting", "def": "除线粒体和植物叶绿体能合成少量蛋白质外，绝大多数蛋白质在细胞质基质中的核糖体上开始合成，然后运至细胞特定部位；正确的亚细胞定位是蛋白质行使功能不可缺少的一部分；大多数真核生物蛋白质新合成的前体必须转运到特定膜结合区域并经蛋白质水解形成成熟功能蛋白；新生蛋白质序列中必须具备特定肽信号指导转运，转运完成后蛋白酶将信号序列去除。", "kp": "ch08_s0_10"}, {"id": "ch08_term_10", "modI": 0, "term": "Signal peptide", "def": "分选信号序列一致性弱，一般在一个或多个正电荷残基后紧跟疏水核区域，但长度和残基构成变化大；原核生物蛋白质也可定向转运到内膜、外膜、周质间隙或细胞外，机制与真核类似，依赖信号肽。", "kp": "ch08_s0_11"}, {"id": "ch08_term_11", "modI": 0, "term": "Yeast two-hybrid (Y2H)", "def": "蛋白质互作研究中最经典的方法；采用必须依赖转录因子才能激活的报告基因表达体系；转录因子同时具有DNA结合结构域（BD）和转录激活结构域（AD），人为将这两个结构域分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和猎物蛋白（prey）；当诱饵和猎物发生互作结合时，转录因子的两个结构域也结合并行使功能，导致报告基因表达；灵敏度高，能检测微弱、瞬间互作，但存在局限：不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_9"}, {"id": "ch08_term_12", "modI": 0, "term": "Affinity chromatography", "def": "利用蛋白质间特异性结合倾向，将一种分子固定作为诱饵诱捕互作蛋白，随后纯化鉴定，为互作提供直接证据；属于物理方法。", "kp": "ch08_s0_17"}]}], "mcq": [{"id": "ch08_mcq_1", "mod": "第八章 蛋白质组学", "modI": 0, "q": "蛋白质组（proteome）的准确定义是？", "o": ["A. 一个生物体所有基因的集合", "B. 一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质", "C. 一个细胞中所有mRNA的集合", "D. 一个蛋白质的所有翻译后修饰形式"], "a": "B", "e": "蛋白质组指一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质，与基因组相对应。A为基因组，C为转录组，D为蛋白质修饰组。", "kp": "ch08_s0_0"}, {"id": "ch08_mcq_2", "mod": "第八章 蛋白质组学", "modI": 0, "q": "二维凝胶电泳（2-DE）分离蛋白质的两个维度依次是？", "o": ["A. 分子质量、等电点", "B. 等电点、分子质量", "C. 疏水性、分子质量", "D. 电荷、疏水性"], "a": "B", "e": "2-DE第一向为等电聚焦（按等电点），第二向为SDS-PAGE（按分子质量）。", "kp": "ch08_s0_4"}, {"id": "ch08_mcq_3", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于MALDI和ESI两种软电离技术，下列说法正确的是？", "o": ["A. MALDI适合与液相色谱联用分析复杂样品", "B. ESI在激光脉冲激发下使样品从基质晶体中挥发并离子化", "C. MALDI常与TOF联用分析肽段精确质量，ESI常与离子阱或三重四极杆联用获取碎片信息", "D. ESI只能分析简单肽混合物"], "a": "C", "e": "MALDI在激光脉冲下使样品从基质晶体挥发离子化，常与TOF联用；ESI使分析物从溶液相电离，适合与液相分离联用，常与离子阱或三重四极杆联用，通过CID获取碎片信息。", "kp": "ch08_s0_8"}, {"id": "ch08_mcq_4", "mod": "第八章 蛋白质组学", "modI": 0, "q": "下列哪种质量分析器具有高灵敏度、宽动态范围、高分辨率和高精度，并可进行多元串联质谱？", "o": ["A. 离子阱（IT）", "B. 飞行时间（TOF）", "C. 四极杆（quadrupole）", "D. 傅里叶变换离子回旋共振（FTICR）"], "a": "D", "e": "FTICR-MS具有高灵敏度、宽动态范围、高分辨率和高精度，可同时选择几个母离子解离，进行多元串联质谱；离子阱灵敏度高但质量精度较低。", "kp": "ch08_s0_5"}, {"id": "ch08_mcq_5", "mod": "第八章 蛋白质组学", "modI": 0, "q": "蛋白质翻译后修饰（PTM）的常见类型不包括？", "o": ["A. 磷酸化", "B. 糖基化", "C. 泛素化", "D. 甲基化", "E. 以上都是常见类型"], "a": "E", "e": "常见PTM包括磷酸化、糖基化、泛素化、乙酰化、硫酸盐化、甲基化等，已知类型超过200种。", "kp": "ch08_s0_9"}, {"id": "ch08_mcq_6", "mod": "第八章 蛋白质组学", "modI": 0, "q": "在基于序列的翻译后修饰预测中，仅使用短序列基序（如[ST]-x-[RK]）容易产生什么问题？", "o": ["A. 假阴性过多", "B. 假阳性过多", "C. 无法识别修饰位点", "D. 计算速度过慢"], "a": "B", "e": "短序列基序几乎在每个蛋白质序列中出现多次，仅根据这一特征预测，大多数情况下会得到假阳性结果。需结合周边环境序列特征和统计学方法（如SVM）减少假阳性。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_7", "mod": "第八章 蛋白质组学", "modI": 0, "q": "支持向量机（SVM）在翻译后修饰预测中的基本思想是？", "o": ["A. 将修饰位点预测转化为分类问题，用最佳超平面区分真实信号与噪声", "B. 通过序列比对寻找同源蛋白", "C. 利用隐马尔可夫模型区分信号肽", "D. 通过质谱峰强度直接定量"], "a": "A", "e": "SVM将数据映射到多维空间，利用线性或非线性函数形成最佳超平面，将真实信号与噪声区别，即把修饰位点预测转化为分类问题（是或不是修饰位点）。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_8", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于蛋白质分选信号，下列说法错误的是？", "o": ["A. 线粒体定向转运肽位于N端，富含正电荷残基，缺少负电荷残基", "B. 叶绿体定位信号位于N端，其转运信号是双向的", "C. 核定位信号位于蛋白质内部，转运后不被剪除", "D. 所有分选信号在转运完成后都会被蛋白酶剪除"], "a": "D", "e": "核定位信号在蛋白质转运后并不会被剪除，而线粒体和叶绿体信号序列通常会被剪除。因此D错误。", "kp": "ch08_s0_10"}, {"id": "ch08_mcq_9", "mod": "第八章 蛋白质组学", "modI": 0, "q": "酵母双杂交（Y2H）系统的局限性不包括？", "o": ["A. 某些蛋白质自身转录激活功能可产生假阳性", "B. 要求互作蛋白定位于细胞核内", "C. 只能检测两个组分的互作", "D. 灵敏度太低，无法检测微弱或瞬间互作"], "a": "D", "e": "Y2H灵敏度非常高，能检测微弱、瞬间的互作。其局限包括假阳性、核内定位要求、只能检测双组分互作等。", "kp": "ch08_s0_13"}, {"id": "ch08_mcq_10", "mod": "第八章 蛋白质组学", "modI": 0, "q": "关于SignalP和WoLF PSORT，下列说法正确的是？", "o": ["A. SignalP仅使用神经网络，不包含隐马尔可夫模型", "B. WoLF PSORT利用K最近相邻分类法预测定位，恢复了对植物蛋白的预测", "C. PSORT能预测植物蛋白亚细胞定位，且对动物及酵母可给出超过20种类型", "D. SignalP只收集了真核生物一个训练数据集"], "a": "B", "e": "WoLF PSORT是PSORT的扩展版本，利用K最近相邻分类法预测定位，恢复了对植物蛋白的预测。SignalP从第二版起加入HMM，收集了3个不同物种训练数据集；PSORT不能预测植物蛋白，对动物及酵母只能给出12种类型。", "kp": "ch08_s0_12"}], "judge": [{"id": "ch08_judge_1", "modI": 0, "q": "蛋白质组是静态的，不随细胞类型、时间、空间和生理状态变化。", "a": "错", "e": "蛋白质组是动态的，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组。", "kp": "ch08_s0_3"}, {"id": "ch08_judge_2", "modI": 0, "q": "二维凝胶电泳（2-DE）第一向按分子质量分离，第二向按等电点分离。", "a": "错", "e": "2-DE第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）。", "kp": "ch08_s0_4"}, {"id": "ch08_judge_3", "modI": 0, "q": "MALDI常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。", "a": "对", "e": "MALDI在激光脉冲激发下使样品从基质晶体中挥发并离子化，适合分析简单肽混合物，常与TOF联用。", "kp": "ch08_s0_5"}, {"id": "ch08_judge_4", "modI": 0, "q": "ESI适合与液相分离手段联用，LC-MS适合复杂样品分析。", "a": "对", "e": "ESI使分析物从溶液相中电离，适合与液相色谱、毛细管电泳等联用，LC-MS适合复杂样品分析。", "kp": "ch08_s0_6"}, {"id": "ch08_judge_5", "modI": 0, "q": "支持向量机（SVM）是一种数据分类方法，将数据映射到多维空间，用最佳超平面区分真实信号与噪声。", "a": "对", "e": "SVM将修饰位点预测转化为分类问题，用已知阳性集和阴性集训练模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_6", "modI": 0, "q": "线粒体定向转运肽位于蛋白质C端，典型长度20~80个残基。", "a": "错", "e": "线粒体定向转运肽位于蛋白质N端，典型长度20~80个残基，富含精氨酸等带正电荷残基及丝氨酸、苏氨酸等带羟基残基。", "kp": "ch08_s0_18"}, {"id": "ch08_judge_7", "modI": 0, "q": "核定位信号位于蛋白质序列内部，转运后不被剪除。", "a": "对", "e": "核定位信号通常是一个或两个包含碱性残基及一致性基序K(K/R)X(K/R)的片段，转运后不被剪除。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_8", "modI": 0, "q": "SignalP最早使用神经网络进行蛋白质分选信号预测，从第二版起加入隐马尔可夫模型提高准确性。", "a": "对", "e": "SignalP是基于网络的亚细胞定位信号预测程序，神经网络算法包含识别信号肽打分和蛋白酶断裂位点打分；HMM用于区分信号肽及N端跨膜锚定片段。", "kp": "ch08_s0_11"}, {"id": "ch08_judge_9", "modI": 0, "q": "酵母双杂交系统（Y2H）是直接检测蛋白质互作的方法，能检测多蛋白复合物。", "a": "错", "e": "Y2H不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_13"}, {"id": "ch08_judge_10", "modI": 0, "q": "遗传学方法可推断蛋白质互作但不能提供直接证明。", "a": "对", "e": "遗传学方法属于小规模蛋白质互作实验，通过观察两个互作候选基因的突变体表型研究，可推断互作但不能提供直接证明；亲和层析等物理方法为互作提供直接证据。", "kp": "ch08_s0_13"}], "fill": [{"id": "ch08_fill_1", "modI": 0, "q": "蛋白质组学是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及________。", "a": "相互作用", "kp": "ch08_s0_0"}, {"id": "ch08_fill_2", "modI": 0, "q": "二维凝胶电泳（2-DE）由Farrell于1975年提出，第一向按________分离，第二向按分子质量分离。", "a": "等电点", "kp": "ch08_s0_4"}, {"id": "ch08_fill_3", "modI": 0, "q": "MALDI常与________质量分析器联用，分析肽段精确质量。", "a": "飞行时间（TOF）", "kp": "ch08_s0_5"}, {"id": "ch08_fill_4", "modI": 0, "q": "ESI常与离子阱或________质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "a": "三重四极杆", "kp": "ch08_s0_5"}, {"id": "ch08_fill_5", "modI": 0, "q": "支持向量机（SVM）是一种数据分类方法，将数据映射到多维空间，用最佳________区分真实信号与噪声。", "a": "超平面", "kp": "ch08_s0_11"}, {"id": "ch08_fill_6", "modI": 0, "q": "线粒体定向转运肽位于蛋白质N端，典型长度20~80个残基，富含精氨酸等带正电荷残基及丝氨酸、苏氨酸等带羟基残基，缺少带________残基。", "a": "负电荷", "kp": "ch08_s0_10"}, {"id": "ch08_fill_7", "modI": 0, "q": "核定位信号位于蛋白质序列内部，通常是一个或两个包含碱性残基及一致性基序________的片段，转运后不被剪除。", "a": "K(K/R)X(K/R)", "kp": "ch08_s0_11"}, {"id": "ch08_fill_8", "modI": 0, "q": "酵母双杂交系统中，人为将转录因子的DNA结合结构域（BD）和转录激活结构域（AD）分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和________。", "a": "猎物蛋白（prey）", "kp": "ch08_s0_13"}], "short": [{"id": "ch08_short_1", "modI": 0, "q": "简述蛋白质组与蛋白质组学的定义及核心思想。", "a": "蛋白质组指一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质；蛋白质组学则是对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及相互作用。核心思想是全局性研究，而非单个蛋白质。蛋白质组是动态的，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组。蛋白质数目通常远大于基因数目，因基因剪接和翻译后修饰所致。", "kp": "ch08_s0_0"}, {"id": "ch08_short_2", "modI": 0, "q": "简述二维凝胶电泳（2-DE）的原理及优缺点。", "a": "原理：第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）。优点：一次可分离几千个蛋白质；采用固相pH梯度干胶条（IPG）可提高分辨率和重复性。缺点：对膜蛋白、碱性蛋白、低丰度蛋白分离检测仍存在不足，且重复性、规模化、自动化受限。", "kp": "ch08_s0_4"}, {"id": "ch08_short_3", "modI": 0, "q": "简述MALDI和ESI两种软电离技术的特点及适用场景。", "a": "MALDI：在激光脉冲激发下使样品从基质晶体中挥发并离子化；适合分析简单肽混合物；常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。ESI：使分析物从溶液相中电离；适合与液相分离手段（如液相色谱、毛细管电泳）联用；LC-MS适合复杂样品分析；常与离子阱或三重四极杆质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "kp": "ch08_s0_8"}, {"id": "ch08_short_4", "modI": 0, "q": "简述基于序列的翻译后修饰预测中支持向量机（SVM）的应用。", "a": "发生PTM的底物蛋白质具有被特定修饰酶识别的序列基序，通常仅含5个残基，倾向存在于无固定三维结构的非球形区域，区域内多为极性、小或骨架柔韧的残基，便于修饰酶接近。但仅考虑短序列基序易产生大量假阳性，如磷酸化位点一致性序列[ST]-x-[RK]几乎在每个蛋白质中出现多次。为减少假阳性，需考虑修饰位点周边环境序列特点，并利用统计学方法。SVM将数据映射到多维空间，用最佳超平面区分真实信号与噪声，即将修饰位点预测转化为分类问题（是或不是）。以激酶磷酸化位点预测为例，用已知阳性集和阴性集训练SVM模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_10"}, {"id": "ch08_short_5", "modI": 0, "q": "简述酵母双杂交系统（Y2H）的原理及局限性。", "a": "原理：采用必须依赖转录因子才能激活的报告基因表达体系。转录因子同时具有DNA结合结构域（BD）和转录激活结构域（AD），人为将这两个结构域分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和猎物蛋白（prey）。当诱饵和猎物发生互作结合时，转录因子的两个结构域也结合并行使功能，导致报告基因表达。还可利用cDNA文库筛选与诱饵蛋白互作的蛋白质。局限性：不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_13"}], "calc": [{"id": "ch08_calc_1", "modI": 0, "q": "论述蛋白质组学的研究内容与意义，并说明其与基因组学的关系。", "a": "蛋白质组学不仅包括对表达蛋白的大规模鉴定和定量分析，还包括对蛋白质功能、细胞定位、修饰以及蛋白质相互作用的确定。中心法则指出信息流从DNA到蛋白质，DNA编码的蛋白质序列决定三维结构，结构决定功能。基因组计划的最终目的是确定基因组如何通过蛋白质实现生命活动。因此，蛋白质组学是连接基因组信息与生物功能的桥梁。本章主要讲述如何利用生物信息学方法进行蛋白质表达、翻译后修饰、定位及相互作用分析。", "steps": "1. 蛋白质组学定义与内容；2. 中心法则与结构功能关系；3. 基因组计划目的；4. 蛋白质组学作为桥梁；5. 生物信息学方法应用。", "kp": "ch08_s0_3"}, {"id": "ch08_calc_2", "modI": 0, "q": "论述蛋白质亚细胞定位的计算预测方法及其优缺点。", "a": "亚细胞定位计算预测方法可分两类。第一类利用蛋白质氨基酸序列中的信号特征，同时需要表达谱数据、系统发育图谱、数据库记录描述内容中的上下文及GO注释词条等额外信息；提供额外信息时准确性比单独基于序列的预测高很多，但额外数据可遇不可求。第二类只利用序列进行同源性搜索或查找共出现的蛋白质结构域；若查询序列与已知亚细胞定位蛋白质同源，可利用同源序列性质进行注释转移，预测较准确，尤其相似性非常好时；若找不到相近同源序列，则需利用机器学习方法（如神经网络、隐马尔可夫模型、支持向量机）对真实分选信号序列进行统计学习。", "steps": "1. 第一类方法：利用信号特征+额外信息；2. 优点：准确性高；3. 缺点：额外数据难获取；4. 第二类方法：仅利用序列；5. 同源搜索与注释转移；6. 机器学习方法应用。", "kp": "ch08_s0_11"}], "term": [{"id": "ch08_term_1", "modI": 0, "term": "Proteome", "def": "一个基因组、一种生物或一种细胞/组织所表达的全套蛋白质；具有动态性，随细胞类型、时间、空间和生理状态变化；同一生物只有一个基因组，但可有多个蛋白质组；蛋白质数目通常远大于基因数目，因基因剪接和翻译后修饰所致。", "kp": "ch08_s0_17"}, {"id": "ch08_term_2", "modI": 0, "term": "Proteomics", "def": "对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量、功能、细胞定位、翻译后修饰及相互作用；由Marc Wilkins等于20世纪90年代初提出；核心思想是全局性研究，而非单个蛋白质；是功能基因组学的核心和连接基因组信息与生物功能的桥梁。", "kp": "ch08_s0_0"}, {"id": "ch08_term_3", "modI": 0, "term": "Two-dimensional gel electrophoresis (2-DE)", "def": "由Farrell于1975年提出；第一向按等电点分离（等电聚焦，IEF），第二向按分子质量分离（SDS-PAGE）；一次可分离几千个蛋白质；采用固相pH梯度干胶条（IPG）可提高分辨率和重复性；但对膜蛋白、碱性蛋白、低丰度蛋白分离检测仍存在不足，且重复性、规模化、自动化受限。", "kp": "ch08_s0_9"}, {"id": "ch08_term_4", "modI": 0, "term": "MALDI", "def": "基质辅助激光解吸电离；在激光脉冲激发下使样品从基质晶体中挥发并离子化；适合分析简单肽混合物；常与飞行时间（TOF）质量分析器联用，分析肽段精确质量。", "kp": "ch08_s0_8"}, {"id": "ch08_term_5", "modI": 0, "term": "ESI", "def": "电喷雾电离；使分析物从溶液相中电离；适合与液相分离手段（如液相色谱、毛细管电泳）联用；LC-MS适合复杂样品分析；常与离子阱或三重四极杆质谱联用，通过碰撞诱导解离（CID）获取肽段碎片信息。", "kp": "ch08_s0_5"}, {"id": "ch08_term_6", "modI": 0, "term": "FTICR-MS", "def": "傅里叶变换离子回旋共振质谱；具有高灵敏度、宽动态范围、高分辨率和高精度（质量准确度可小于mg/L）；可一次分析数百个完整蛋白质分子；具备多元串联质谱能力，可同时选择几个母离子解离，提高通量；但操作复杂、肽段断裂效率低、价格昂贵。", "kp": "ch08_s0_7"}, {"id": "ch08_term_7", "modI": 0, "term": "Post-translational modification (PTM)", "def": "蛋白质翻译合成后，需经过功能基团的共价修饰才能获得相应活性、结构与功能；已知PTM类型超过200种，常见包括磷酸化、糖基化、泛素化、乙酰化和硫酸盐化等；通过改变分子大小、疏水性及整体构象影响蛋白质生物学功能；可直接影响到蛋白质间相互作用以及蛋白质在不同亚细胞区域的分布。", "kp": "ch08_s0_9"}, {"id": "ch08_term_8", "modI": 0, "term": "Support vector machine (SVM)", "def": "一种数据分类方法；将数据映射到多维空间，用最佳超平面区分真实信号与噪声；将修饰位点预测转化为分类问题（是或不是）；以激酶磷酸化位点预测为例，用已知阳性集和阴性集训练SVM模型，可较准确识别磷酸化位点。", "kp": "ch08_s0_9"}, {"id": "ch08_term_9", "modI": 0, "term": "Protein sorting / protein targeting", "def": "除线粒体和植物叶绿体能合成少量蛋白质外，绝大多数蛋白质在细胞质基质中的核糖体上开始合成，然后运至细胞特定部位；正确的亚细胞定位是蛋白质行使功能不可缺少的一部分；大多数真核生物蛋白质新合成的前体必须转运到特定膜结合区域并经蛋白质水解形成成熟功能蛋白；新生蛋白质序列中必须具备特定肽信号指导转运，转运完成后蛋白酶将信号序列去除。", "kp": "ch08_s0_10"}, {"id": "ch08_term_10", "modI": 0, "term": "Signal peptide", "def": "分选信号序列一致性弱，一般在一个或多个正电荷残基后紧跟疏水核区域，但长度和残基构成变化大；原核生物蛋白质也可定向转运到内膜、外膜、周质间隙或细胞外，机制与真核类似，依赖信号肽。", "kp": "ch08_s0_11"}, {"id": "ch08_term_11", "modI": 0, "term": "Yeast two-hybrid (Y2H)", "def": "蛋白质互作研究中最经典的方法；采用必须依赖转录因子才能激活的报告基因表达体系；转录因子同时具有DNA结合结构域（BD）和转录激活结构域（AD），人为将这两个结构域分隔，将可能互作的两个基因cDNA分别与BD和AD融合，产生诱饵蛋白（bait）和猎物蛋白（prey）；当诱饵和猎物发生互作结合时，转录因子的两个结构域也结合并行使功能，导致报告基因表达；灵敏度高，能检测微弱、瞬间互作，但存在局限：不是直接检测方法，某些蛋白质自身转录激活功能可产生假阳性；要求互作蛋白定位于细胞核内，细胞质或膜蛋白难以分析；只能检测两个组分互作，多蛋白复合物检测不到。", "kp": "ch08_s0_9"}, {"id": "ch08_term_12", "modI": 0, "term": "Affinity chromatography", "def": "利用蛋白质间特异性结合倾向，将一种分子固定作为诱饵诱捕互作蛋白，随后纯化鉴定，为互作提供直接证据；属于物理方法。", "kp": "ch08_s0_17"}], "preview": {"main": "本章从中心法则与基因组计划成就出发，引出蛋白质组与蛋白质组学概念，说明后基因组时代研究重心转向蛋白质。随后介绍蛋白质大规模分离鉴定技术（2-DE、质谱、色谱-质谱、DIGE、ICAT、SELDI、蛋白质芯片等）及翻译后修饰、亚细胞定位预测，最后讨论蛋白质相互作用检测与预测方法。", "questions": ["蛋白质组与基因组相比，为什么研究更复杂困难？", "二维电泳、质谱及色谱-质谱联用各自解决蛋白质分离鉴定中的什么问题？", "如何预测和鉴定蛋白质翻译后修饰及亚细胞定位？", "酵母双杂交、亲和层析、免疫共沉淀等检测蛋白质互作的方法各有什么优缺点？", "基于基因组信息的互作预测方法（基因次序、结构域融合、系统发育谱、镜像树等）的基本原理是什么？"]}, "appcards": [{"front": "为什么说基因组计划的最终目的仍是理解蛋白质？蛋白质组与蛋白质组学分别指什么？", "back": "中心法则：DNA序列编码蛋白质序列，蛋白质序列决定三维结构，结构决定功能；基因组计划最终要理解蛋白质如何实现生命活动。蛋白质组：一个特定样本（细胞、组织或器官）中所表达的一整套蛋白质。蛋白质组学：对样本中所有蛋白质进行系统研究，包括大规模鉴定与定量分析等。", "points": "中心法则链条；蛋白质组定义（特定样本、整套蛋白质）；蛋白质组学定义（系统研究、大规模鉴定与定量）", "mod": 0, "modName": "第八章 蛋白质组学", "level": "掌握", "src": "生成"}, {"front": "蛋白质大规模分离鉴定中，2-DE、DIGE、ICAT、SELDI、蛋白质芯片各有什么特点或用途？", "back": "2-DE：经典二维电泳分离，但向质谱过渡操作繁琐。DIGE：荧光差异凝胶电泳，用于差异比较。ICAT：同位素亲和标签，用于定量比较。SELDI：可先纯化，能分析复杂生物样品、疏水性蛋白、极端等电点蛋白及低分子质量蛋白（<25 kDa），样品量少、重复性好，适合临床诊断与疾病标志物筛选。蛋白质芯片：高通量检测蛋白质。", "points": "2-DE与质谱衔接问题；DIGE/ICAT用于差异与定量；SELDI适用复杂/低丰度/低分子质量蛋白及临床标志物；蛋白质芯片高通量", "mod": 0, "modName": "第八章 蛋白质组学", "level": "掌握", "src": "生成"}, {"front": "酵母双杂交系统检测蛋白质互作的原理是什么？有哪些主要局限？", "back": "原理：诱饵蛋白与DNA结合结构域（BD）融合，猎物蛋白与转录激活结构域（AD）融合；若诱饵与猎物互作，BD与AD靠近，激活报告基因转录。局限：不是直接检测互作的方法；某些蛋白质自身具有转录激活功能，可产生假阳性；灵敏度高但可能存在假阴性/假阳性等问题。", "points": "BD-诱饵、AD-猎物；互作使BD与AD靠近激活报告基因；非直接检测；自激活导致假阳性", "mod": 0, "modName": "第八章 蛋白质组学", "level": "掌握", "src": "生成"}, {"front": "基于基因组信息预测蛋白质互作的方法有哪些？其基本依据是什么？", "back": "方法包括：基因次序（基因邻近）、基因/结构域融合、系统发育谱、镜像树、interologs等。依据：基因次序在演化中保守，可指示功能关系；结构域融合事件提示分离基因产物可能互作；系统发育谱相同或相似提示功能关联；镜像树中两个蛋白质家族系统发育树进化距离矩阵强相关（r≥0.8）且拓扑一致，提示功能相关；interologs基于已知互作在物种间的保守性。", "points": "基因次序/邻近；基因或结构域融合；系统发育谱；镜像树（r≥0.8、拓扑一致）；interologs；共同依据是演化保守性与功能关联", "mod": 0, "modName": "第八章 蛋白质组学", "level": "掌握", "src": "生成"}]};